import { Capacitor } from '@capacitor/core'
import { LocalNotifications } from '@capacitor/local-notifications'
import type { HourKey } from './prayer'

/**
 * Avisos diarios de las Horas menores y de la tarde (solo dentro del APK). Petición de Lucas,
 * 29/09/2026: "a las nueve, a las doce, a las tres, a las seis, a las nueve de la noche, una
 * notificación de si quiero rezar". Laudes no, porque su hora es variable.
 *
 * Son notificaciones LOCALES: las programa el propio móvil con repetición diaria, sin servidor
 * ni red. La hora es la del reloj del móvil. Tocar el aviso abre esa Hora con la fecha de hoy.
 */
const AVISOS: { id: number; hour: HourKey; label: string; hora: number }[] = [
  { id: 9001, hour: 'tertia', label: 'Tercia', hora: 9 },
  { id: 9002, hour: 'sexta', label: 'Sexta', hora: 12 },
  { id: 9003, hour: 'nona', label: 'Nona', hora: 15 },
  { id: 9004, hour: 'vesperae', label: 'Vísperas', hora: 18 },
  { id: 9005, hour: 'completorium', label: 'Completas', hora: 21 },
]

export function avisosDisponibles(): boolean {
  return Capacitor.isNativePlatform()
}

/** Programa (activo) o cancela (inactivo) los avisos. Idempotente: siempre cancela y reprograma. */
export async function sincronizarAvisosHoras(activo: boolean): Promise<void> {
  if (!avisosDisponibles()) return
  await LocalNotifications.cancel({ notifications: AVISOS.map(({ id }) => ({ id })) })
  if (!activo) return

  let permiso = await LocalNotifications.checkPermissions()
  if (permiso.display !== 'granted') permiso = await LocalNotifications.requestPermissions()
  if (permiso.display !== 'granted') return

  await LocalNotifications.schedule({
    notifications: AVISOS.map(({ id, hour, label, hora }) => ({
      id,
      title: label,
      body: `Es hora de rezar ${label}`,
      schedule: { on: { hour: hora, minute: 0 }, allowWhileIdle: true },
      extra: { hour },
    })),
  })
}

/** Llama a `abrir` con la Hora del aviso que Lucas toque. */
export function alTocarAvisoHora(abrir: (hour: HourKey) => void): void {
  if (!avisosDisponibles()) return
  void LocalNotifications.addListener('localNotificationActionPerformed', ({ notification }) => {
    const hour = notification.extra?.hour as HourKey | undefined
    if (hour) abrir(hour)
  })
}
