import { createApp } from 'vue'
import { registerSW } from 'virtual:pwa-register'
import { Capacitor } from '@capacitor/core'
import './style.css'
import App from './App.vue'
import {
  programarComprobacionDeActualizaciones,
  solicitarRecargaPorActualizacion,
} from './lib/sw-update'

const DEV_SW_RESET_KEY = 'orante:dev-sw-reset'

async function resetDevelopmentServiceWorker(): Promise<void> {
  if (!('serviceWorker' in navigator)) {
    return
  }

  const hadController = Boolean(navigator.serviceWorker.controller)
  const registrations = await navigator.serviceWorker.getRegistrations()
  const unregisterResults = await Promise.all(registrations.map((registration) => registration.unregister()))
  const cacheNames = 'caches' in window ? await caches.keys() : []

  await Promise.all(cacheNames.map((cacheName) => caches.delete(cacheName)))

  const removedStaleData = unregisterResults.some(Boolean) || cacheNames.length > 0
  if (hadController && removedStaleData && sessionStorage.getItem(DEV_SW_RESET_KEY) !== 'done') {
    sessionStorage.setItem(DEV_SW_RESET_KEY, 'done')
    window.location.reload()
    return
  }

  sessionStorage.removeItem(DEV_SW_RESET_KEY)
}

if (import.meta.env.DEV) {
  window.addEventListener('load', () => {
    resetDevelopmentServiceWorker().catch(() => {
      // A stale development service worker is annoying, but should not block the app.
    })
  })
} else if (Capacitor.isNativePlatform()) {
  // Dentro del APK la app va empaquetada en el propio APK: ya está entera en el móvil y no
  // hay nada que precachear ni versión nueva que pedir a un servidor. Sin service worker.
} else {
  // `immediate: true` registra el SW sin esperar al evento `load`: la primera visita deja la
  // app entera (shell + librería litúrgica + Biblia) precacheada cuanto antes, que es lo que
  // permite rezar sin conexión después. Ver app/src/lib/sw-update.ts para por qué la recarga
  // por actualización no es automática a secas.
  registerSW({
    immediate: true,
    onNeedReload: solicitarRecargaPorActualizacion,
    onRegisteredSW: (_url, registration) => programarComprobacionDeActualizaciones(registration),
  })
}

createApp(App).mount('#app')
