// Acumula sobre lo que ya haya en el campo -- usado por el pegado manual de texto largo desde
// el portapapeles (abajo). La sincronización automática del cron de YouTube (más abajo) NO usa
// esta función: esa sustituye el campo entero en vez de acumular, ver syncRemoteIntentions.
function appendIntentions(text: string): void {
  const trimmed = text.trim()
  if (!trimmed) {
    return
  }
  const existing = customIntentions.value.trim()
  customIntentions.value = existing ? `${existing}\n\n${trimmed}` : trimmed
}

async function pasteLongClipboardIntentions(): Promise<void> {
  if (!navigator.clipboard?.readText) {
    return
  }

  try {
    const clipboardText = await navigator.clipboard.readText()
    const pastedText = clipboardText.trim()

    if (pastedText.length > 200) {
      appendIntentions(pastedText)
    }
  } catch {
    return
  }
}

// Trae automáticamente, sin acción de Lucas, las peticiones que el cron de comentarios de
// YouTube clasificó y publicó en el repo público (no puede escribir en localStorage de su
// móvil directamente -- esto es lo más cerca de "automático" que permite una app estática).
// SUSTITUYE el campo entero cuando llega un lote nuevo, no lo acumula (decisión de Lucas,
// 29/08/2026, revierte el diseño "append" del 28/08). El cron trae una ventana rodante de 24h
// que se solapa mucho día a día, así que acumular producía peticiones casi duplicadas de un
// día para otro (visto en producción: la petición de Florencia/David Eduardo/Marta apareció
// dos veces seguidas). El campo solo guarda el "id" del último lote incorporado -- si Lucas no
// abre la app un día, ese lote se pierde sin recuperación, es el trade-off aceptado a cambio.
// Falla en silencio (sin conexión, CORS, JSON roto, etc.) -- es una mejora silenciosa, nunca
// debe bloquear ni ensuciar la pantalla de inicio. Rama `data` dedicada (no `main`, no
// `app-dist`) -- el cron nunca toca `main` de un repo sin Lucas mirando en vivo (regla global),
// y `app-dist` la pisa por completo cada `pnpm app:deploy`.
const INTENTIONS_SYNC_URL = 'https://raw.githubusercontent.com/lucasague/liturgiadelashoras/data/intenciones.json'
const INTENTIONS_LAST_SYNCED_ID_KEY = 'orante:intenciones-last-synced-id'

const isSyncingIntentions = ref(false)
// Aviso discreto bajo el campo de Preces cuando la descarga de intenciones falla. Las
// intenciones salen de los comentarios de YouTube del día: son de las poquísimas cosas de
// esta app que NO pueden funcionar sin conexión. Lo que sí puede es no gritarlo en inglés ni
// romper el rezo — se avisa en español y se sigue con lo último que se descargó.
const intentionsNotice = ref('')
// Reloj de baja frecuencia solo para recalcular "¿está viejo el lote de intenciones?" --
// no depende del reloj local a secas (regla dura del proyecto), se compara siempre contra
// LUCAS_TIME_ZONE. Se actualiza cada 60s, suficiente para un aviso que no es urgente al segundo.
const intentionsStaleCheckNow = ref(new Date())
let intentionsStaleCheckTimer: ReturnType<typeof setInterval> | undefined

const isIntentionsBatchStale = computed(() => {
  const lastSyncedId = readStorage<string>(INTENTIONS_LAST_SYNCED_ID_KEY, '')
  const now = intentionsStaleCheckNow.value
  if (hourInTimeZone(LUCAS_TIME_ZONE, now) < 4) {
    return false
  }
  if (!lastSyncedId) {
    return true
  }
  const loadedDate = dateInTimeZoneFromIso(lastSyncedId, LUCAS_TIME_ZONE)
  return loadedDate !== todayInTimeZone(LUCAS_TIME_ZONE, now)
})

/** Texto del aviso cuando no se han podido traer las intenciones del día. Si el campo ya
 *  tiene algo (lo que se bajó la última vez, que persiste en localStorage), se dice que eso
 *  es lo de antes, no lo de hoy. */
function intentionsOfflineNotice(): string {
  const hayCache = customIntentions.value.trim().length > 0
  const cabecera = sinConexion() ? 'Sin conexión' : 'No hay conexión con la nube'

  return hayCache
    ? `${cabecera}: se muestran las últimas intenciones descargadas, puede que no sean las de hoy.`
    : `${cabecera}: no se han podido cargar las intenciones de hoy.`
}

async function syncRemoteIntentions(options: { force?: boolean } = {}): Promise<void> {
  const { force = false } = options
  if (force) {
    isSyncingIntentions.value = true
    intentionsNotice.value = ''
  }
  try {
    const res = await fetch(INTENTIONS_SYNC_URL, { cache: 'no-store' })
    if (!res.ok) {
      intentionsNotice.value = intentionsOfflineNotice()
      return
    }
    const data = (await res.json()) as { id?: string; text?: string }
    if (!data.id || !data.text?.trim()) {
      intentionsNotice.value = 'Todavía no hay intenciones publicadas para hoy.'
      return
    }

    const lastSyncedId = readStorage<string>(INTENTIONS_LAST_SYNCED_ID_KEY, '')
    intentionsNotice.value = ''
    if (!force && data.id === lastSyncedId) {
      return
    }

    customIntentions.value = data.text.trim()
    localStorage.setItem(INTENTIONS_LAST_SYNCED_ID_KEY, JSON.stringify(data.id))
  } catch (syncError) {
    // Nunca se propaga: sin intenciones se reza igual. Sólo se deja el aviso, en español.
    intentionsNotice.value = esErrorDeRed(syncError)
      ? intentionsOfflineNotice()
      : 'No se han podido cargar las intenciones de hoy.'
  } finally {
    if (force) {
      isSyncingIntentions.value = false
    }
  }
}

