// contrario: aquí la app también ESCRIBE, con un token fine-grained acotado solo a este
// repo y solo a Contents (VITE_LITURGIADELASHORAS_CONTENTS_TOKEN, en app/.env.local, no
// versionado -- si falta, se guarda igual localmente en memoria pero no sale a la nube).
// Un solo objeto que se sustituye entero por corrida (mismo patrón "replace" que
// intenciones.json), clave por fecha para no mezclar selecciones de días distintos.
const CHANT_SELECTIONS_REPO = 'lucasague/liturgiadelashoras'
const CHANT_SELECTIONS_BRANCH = 'data'
const CHANT_SELECTIONS_PATH = 'canticos.json'
const CHANT_SELECTIONS_RAW_URL = `https://raw.githubusercontent.com/${CHANT_SELECTIONS_REPO}/${CHANT_SELECTIONS_BRANCH}/${CHANT_SELECTIONS_PATH}`
const CHANT_SELECTIONS_API_URL = `https://api.github.com/repos/${CHANT_SELECTIONS_REPO}/contents/${CHANT_SELECTIONS_PATH}`
const CHANT_SELECTIONS_TOKEN = import.meta.env.VITE_LITURGIADELASHORAS_CONTENTS_TOKEN
let chantSelectionsSha: string | null = null
let chantSelectionsLoadedForDate = ''
let chantSelectionsSyncTimer = 0

function encodeUtf8Base64(text: string): string {
  return btoa(unescape(encodeURIComponent(text)))
}

async function loadRemoteChantSelections(dateKey: string): Promise<void> {
  try {
    const res = await fetch(CHANT_SELECTIONS_RAW_URL, { cache: 'no-store' })
    if (!res.ok) return
    const data = (await res.json()) as {
      fecha?: string
      selecciones?: Record<string, { key: string; capoOffset: number }>
      misaCanciones?: Record<string, string>
    }
    if (data.fecha === dateKey) {
      if (data.selecciones) {
        chantSelections.value = { ...data.selecciones }
      }
      if (data.misaCanciones) {
        massSongSelections.value = { ...data.misaCanciones }
      }
    }
  } catch {
    // sin conexión, o el archivo aún no existe: se sigue con lo que haya en memoria
  }
}

async function saveRemoteChantSelections(dateKey: string): Promise<void> {
  if (!CHANT_SELECTIONS_TOKEN) return

  try {
    if (chantSelectionsSha === null) {
      const current = await fetch(`${CHANT_SELECTIONS_API_URL}?ref=${CHANT_SELECTIONS_BRANCH}`, {
        headers: { Authorization: `Bearer ${CHANT_SELECTIONS_TOKEN}` },
      })
      if (current.ok) {
        chantSelectionsSha = ((await current.json()) as { sha: string }).sha
      }
    }

    const payload = JSON.stringify(
      { fecha: dateKey, selecciones: chantSelections.value, misaCanciones: massSongSelections.value },
      null,
      2,
    )
    const res = await fetch(CHANT_SELECTIONS_API_URL, {
      method: 'PUT',
      headers: {
        Authorization: `Bearer ${CHANT_SELECTIONS_TOKEN}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        message: `chore: cánticos del ${dateKey}`,
        content: encodeUtf8Base64(payload),
        branch: CHANT_SELECTIONS_BRANCH,
        sha: chantSelectionsSha ?? undefined,
      }),
    })
    if (res.ok) {
      chantSelectionsSha = ((await res.json()) as { content: { sha: string } }).content.sha
    }
  } catch {
    // sin conexión: se pierde ese guardado puntual, el próximo cambio lo reintenta
  }
}

function scheduleRemoteChantSelectionsSave(): void {
  window.clearTimeout(chantSelectionsSyncTimer)
  const dateKey = selectedDate.value
  chantSelectionsSyncTimer = window.setTimeout(() => {
    void saveRemoteChantSelections(dateKey)
  }, 1500)
}

