function capoOffsetForSection(section: PrayerSectionData): number {
  return chantSelections.value[section.title]?.capoOffset ?? 0
}

function inheritedCapoOffsetForSection(section: PrayerSectionData): number {
  return inheritedCapoOffsets.value[section.title] ?? 0
}

/** Cántico guardado para esta sección (nube canticos.json del día, o lo que ya recogió
 * chantSelections en esta sesión) -- PrayerSection.vue lo prioriza sobre el localStorage del
 * último rezo y sobre la heurística de familia preferida. */
function chantKeyForSection(section: PrayerSectionData): string | undefined {
  return chantSelections.value[section.title]?.key
}

/** Claves de cántico ya elegidas por las secciones anteriores de la misma Hora (recorriendo
 * por índice, igual que inheritedCapoOffsetForSection) -- Lucas, 05/09/2026: nunca repetir
 * melodía entre salmos/cánticos dentro del mismo día. */
function takenChantKeysForSection(section: PrayerSectionData): string[] {
  const index = sections.value.indexOf(section)
  if (index <= 0) {
    return []
  }

  return sections.value
    .slice(0, index)
    .map((previous) => chantSelections.value[previous.title]?.key)
    .filter((key): key is string => Boolean(key))
}

/** Al ciclar el capo de una sección, ese mismo desplazamiento se pone a esa sección y a todas
 * las posteriores con ChantPicker (pedido de Lucas 01/09/2026): bajar uno el primer salmo baja
 * uno todo lo que sigue; dejarlo a cero en el segundo deja el resto a cero. Es absoluto, no
 * acumulativo (Lucas lo pidió así expresamente): las posteriores copian el valor, no suman. */
function propagateCapoOffset(fromIndex: number, offset: number): void {
  const next = { ...chantSelections.value }
  const inherited = { ...inheritedCapoOffsets.value }
  sections.value.forEach((section, index) => {
    const pool = LAUDES_CHANT_POOLS[section.title]
    if (index < fromIndex || !pool?.length) return
    const current = next[section.title] ?? { key: LAUDES_CHANT_DEFAULTS[section.title] ?? pool[0].key, capoOffset: 0 }
    next[section.title] = { ...current, capoOffset: offset }
    // La sección tocada conserva su herencia (así su ciclo puede volver a ella); las
    // posteriores heredan el valor nuevo.
    if (index > fromIndex) inherited[section.title] = offset
  })
  chantSelections.value = next
  inheritedCapoOffsets.value = inherited
}

function alternativeIndexForSection(section: PrayerSectionData): number | undefined {
  if (section.title === 'Salmo invitatorio') {
    return invitatoryPsalmIndex.value
