  if (CURATED_MASS_SONG_TITLES.has(section.title)) {
    const savedLabel = massSongSelections.value[section.title]
    const index = savedLabel ? section.alternatives?.findIndex((alt) => alt.label === savedLabel) : undefined
    return index !== undefined && index >= 0 ? index : undefined
  }

  return undefined
}

function setAlternativeIndexForSection(section: PrayerSectionData, index: number): void {
  if (section.title === 'Salmo invitatorio') {
    invitatoryPsalmIndex.value = index
    return
  }

  if (CURATED_MASS_SONG_TITLES.has(section.title)) {
