  showPrayerOptionPrompt.value = false
  maybeShowSolemnityLordPrayerPrompt()
}

function shouldPreferFirstPrayerOption(options: LoadedPrayer['options']): boolean {
  return (
    optionTitle(options[0], 0) === 'Corpus Christi' &&
    options.some((option, index) => optionTitle(option, index) === 'Domingo ordinario')
  )
}

function resolvePrayerOptionSelection(): void {
  const options = loaded.value?.options ?? []

  if (options.length <= 1) {
    activeOption.value = 0
    showPrayerOptionPrompt.value = false
    return
  }

  if (shouldPreferFirstPrayerOption(options)) {
    activeOption.value = 0
    showPrayerOptionPrompt.value = true
    return
  }

  const selectedIndex = prayerOptionSelections.value[optionSelectionKey.value]
  if (Number.isInteger(selectedIndex) && selectedIndex >= 0 && selectedIndex < options.length) {
    activeOption.value = selectedIndex
    showPrayerOptionPrompt.value = false
    return
  }

  activeOption.value = 0
  showPrayerOptionPrompt.value = true
}

function clampFontScale(value: unknown): number {
  const parsed = Number(value)
  if (!Number.isFinite(parsed)) return FONT_SCALE_DEFAULT
  return Math.min(FONT_SCALE_STEPS, Math.max(0, Math.round(parsed)))
}

// Valor ya guardado bajo la clave nueva ('orante:font-scale-v2'): está en la escala
// actual (0-20), no hace falta migrar nada más que el rango 0.9-1.28 de muy atrás.
function migrateFontScale(value: unknown): number {
  const parsed = Number(value)
  if (!Number.isFinite(parsed)) return FONT_SCALE_DEFAULT

  if (parsed >= 0 && parsed <= FONT_SCALE_STEPS) {
    return parsed
  }

  if (parsed >= FONT_SCALE_MIN && parsed <= FONT_SCALE_MAX) {
    return Math.round(((parsed - FONT_SCALE_MIN) / (FONT_SCALE_MAX - FONT_SCALE_MIN)) * FONT_SCALE_STEPS)
  }

  return FONT_SCALE_DEFAULT
}

// Punto de entrada real: prueba la clave nueva primero; si no existe, migra la vieja
// (escala 0-10, o más atrás 0.9-1.28) duplicando el valor para conservar el mismo
// tamaño visual bajo la escala nueva de 0-20. Sin ninguna de las dos, el default (4).
function readFontScale(): number {
  const current = readStorage<number | null>(FONT_SCALE_STORAGE_KEY, null)
  if (current !== null) {
    return clampFontScale(migrateFontScale(current))
  }

  const legacy = readStorage<number | null>(FONT_SCALE_LEGACY_STORAGE_KEY, null)
  if (legacy !== null) {
    const parsed = Number(legacy)
    if (Number.isFinite(parsed)) {
      if (parsed >= 0 && parsed <= FONT_SCALE_LEGACY_STEPS) {
        return clampFontScale(parsed * (FONT_SCALE_STEPS / FONT_SCALE_LEGACY_STEPS))
      }
      if (parsed >= FONT_SCALE_MIN && parsed <= FONT_SCALE_MAX) {
        return clampFontScale(((parsed - FONT_SCALE_MIN) / (FONT_SCALE_MAX - FONT_SCALE_MIN)) * FONT_SCALE_STEPS)
      }
    }
  }

  return FONT_SCALE_DEFAULT
}

function closestAutoScrollPresetIndex(value: unknown): number {
  const speed = Number(value)
  if (!Number.isFinite(speed)) {
    return 0
  }

  let closestIndex = 0
  let closestDistance = Number.POSITIVE_INFINITY

  AUTO_SCROLL_PRESETS.forEach((preset, index) => {
    const distance = Math.abs(preset.speed - speed)
    if (distance < closestDistance) {
      closestDistance = distance
      closestIndex = index
    }
  })

  return closestIndex
}

function clampAutoScrollSpeed(value: unknown): number {
  const speed = Number(value)
  if (!Number.isFinite(speed)) return AUTO_SCROLL_DEFAULT
  return AUTO_SCROLL_PRESETS[closestAutoScrollPresetIndex(speed)].speed
}

function setAutoScrollPreset(index: number): void {
  autoScrollPresetIndex.value = index
}

function migrateAutoScrollSpeed(value: unknown): number {
  const speed = Number(value)
  if (!Number.isFinite(speed)) return AUTO_SCROLL_DEFAULT

  if (speed > AUTO_SCROLL_MAX && speed <= AUTO_SCROLL_OLD_MAX) {
    return clampAutoScrollSpeed((speed / AUTO_SCROLL_OLD_MAX) * AUTO_SCROLL_MAX)
  }

  return clampAutoScrollSpeed(speed)
}

