function liturgicalColorForInfo(info: LoadedPrayer['info'] | undefined): string {
  const paletteColor = liturgicalPaletteColor(info?.color)

  if (paletteColor) {
    return paletteColor
  }

  return normalizeLiturgicalColor(info?.color_hex || LITURGICAL_PALETTE.GREEN, LITURGICAL_PALETTE.GREEN)
}

function liturgicalPaletteColor(color: unknown): string | undefined {
  const key = String(color ?? '')
    .trim()
    .toUpperCase()

  return LITURGICAL_PALETTE[key]
}

function normalizeLiturgicalColor(colorHex: string, fallback = LITURGICAL_PALETTE.GREEN): string {
  const normalized = colorHex.trim().toLowerCase()
  const paletteColor = liturgicalPaletteColor(normalized)

  if (paletteColor) {
    return paletteColor
  }

  if (normalized === 'white') {
    return OFF_WHITE
  }

  const normalizedHex = normalized.startsWith('#') ? normalized : `#${normalized}`
  const sourcePaletteColor = SOURCE_LITURGICAL_HEX_PALETTE[normalizedHex]

  if (sourcePaletteColor) {
    return sourcePaletteColor
  }

  const raw = normalized.startsWith('#') ? normalized.slice(1) : normalized
  const isRgb3 = /^([0-9a-f]{3})$/i.test(raw)
  const isRgb6 = /^([0-9a-f]{6})$/i.test(raw)
  const isRgba8 = /^([0-9a-f]{8})$/i.test(raw)

  if (!isRgb3 && !isRgb6 && !isRgba8) {
    return fallback
  }

  const hex = isRgb3
    ? raw
        .split('')
        .map((char) => char + char)
        .join('')
    : raw.slice(0, 6)

  const r = Number.parseInt(hex.slice(0, 2), 16)
  const g = Number.parseInt(hex.slice(2, 4), 16)
  const b = Number.parseInt(hex.slice(4, 6), 16)

  if (r >= 245 && g >= 245 && b >= 245) {
    return OFF_WHITE
  }

  return `#${hex}`
}

function capitalizeFirst(value: string): string {
  return value ? value.charAt(0).toUpperCase() + value.slice(1) : value
}

function formatTitleDate(date: Date, includeWeekday: boolean): string {
  const dateText = new Intl.DateTimeFormat('es-ES', {
    weekday: includeWeekday ? 'long' : undefined,
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  }).format(date)

  return capitalizeFirst(dateText.replace(',', ''))
}

function formatHomeDate(date: Date): string {
  return new Intl.DateTimeFormat('es-ES', {
    day: 'numeric',
    month: 'long',
  }).format(date)
}

function startsWithWeekday(value: string): boolean {
  return /^(lunes|martes|mi\u00e9rcoles|jueves|viernes|s\u00e1bado|domingo)\b/i.test(value.trim())
}

function isOrdinaryFeriaTitle(value: string): boolean {
  return /tiempo ordinario/i.test(value) || /\bsemana\b/i.test(value)
}

function shouldIncludeCelebrationInClipboard(): boolean {
  const celebration = currentInfo.value?.celebration?.trim()
  const rank = currentInfo.value?.rank

  if (!celebration || isOrdinaryFeriaTitle(celebration)) {
    return false
  }

  return rank !== 'FERIA' && rank !== 'WEEKDAY'
}

function buildAutoScrollClipboardText(): string {
  const hourTitle = hourNames[activeHour.value]
  const prefix = `${hourTitle} Cantados`
  const celebration = currentInfo.value?.celebration?.trim()

  if (celebration && shouldIncludeCelebrationInClipboard()) {
    const separator = startsWithWeekday(celebration) ? ', ' : ' - '
    const dateText = formatTitleDate(selectedDateObject.value, !startsWithWeekday(celebration))

    return `${prefix} - ${celebration}${separator}${dateText}`
  }

  return `${prefix} - ${formatTitleDate(selectedDateObject.value, true)}`
}

// Nombre de sección tal como debe salir en la descripción del vídeo -- distinto, a propósito,
// del título real de sección (LAUDES_CHANT_POOLS/section.title) que usa el ChantPicker: formato
// exacto pedido por Lucas (29/08/2026), más corto que el título litúrgico completo.
const VIDEO_DESCRIPTION_SECTION_LABELS: Record<string, string> = {
  'Invocación inicial': 'Invocación inicial',
  Himno: 'Himno',
  'Primer salmo': '1er salmo',
  'Segundo salmo': '2º salmo',
  'Tercer salmo': '3er salmo',
  'Responsorio breve': 'Responsorio',
  'Cántico de Zacarías': 'Cántico Evangélico',
  Padrenuestro: 'Padrenuestro',
}

function chantDescriptionLine(sectionTitle: string): string | undefined {
  const selection = chantSelections.value[sectionTitle]
  const key = selection?.key ?? LAUDES_CHANT_DEFAULTS[sectionTitle]
  const variant = key ? chantVariant(sectionTitle, key) : undefined

  if (!variant) {
    return undefined
  }

  const capo = Math.max(0, variant.capo + (selection?.capoOffset ?? 0))
  const displayTitle = VIDEO_DESCRIPTION_SECTION_LABELS[sectionTitle] ?? sectionTitle

  return formatChantDescriptionLine(displayTitle, capo, variant.chords)
}

/** Descripción del vídeo: cántico+capo+acordes elegidos hoy, sección por sección. Pensada para
 * la fase 3 (subida automática a YouTube) — ver memoria de proyecto plan-fase3-subida-youtube.
 * El formato exacto (y qué marcado de YouTube funciona) vive en ./lib/video-description.ts. */
function buildVideoDescription(): string {
  if (activeHour.value !== 'laudes') {
    return ''
  }

  const lines = Object.keys(LAUDES_CHANT_POOLS)
    .map(chantDescriptionLine)
    .filter((line): line is string => Boolean(line))

  return buildVideoDescriptionText(lines)
}

function fallbackCopyText(text: string): boolean {
  const textarea = document.createElement('textarea')
  textarea.value = text
  textarea.setAttribute('readonly', 'true')
  textarea.style.position = 'fixed'
  textarea.style.top = '0'
  textarea.style.left = '0'
  textarea.style.opacity = '0'
  textarea.style.pointerEvents = 'none'
  document.body.appendChild(textarea)
  textarea.focus()
  textarea.select()
  textarea.setSelectionRange(0, textarea.value.length)

  try {
    return document.execCommand('copy')
  } catch {
    return false
  } finally {
    document.body.removeChild(textarea)
  }
}

// Repo y rama donde la app deja título+descripción para que la rutina en la nube que sube el
// vídeo a YouTube al día siguiente sepa qué ponerle. Rama dedicada y estable (nadie la
// force-pushea) — a propósito distinta de automation/laudes-yt-cron, que el cron de comentarios
// reconstruye y force-pushea a diario y borraría este archivo si compartieran rama.
const GITHUB_METADATA_REPO = 'lucasague/laudes'
const GITHUB_METADATA_BRANCH = 'automation/laudes-video-metadata'

function toBase64Utf8(value: string): string {
  return btoa(unescape(encodeURIComponent(value)))
}

/** Deja título+descripción en un archivo del repo (API de contenidos de GitHub) para que la
 * rutina en la nube los recoja. No hace nada si no hay token configurado
 * (VITE_GITHUB_METADATA_TOKEN, fine-grained PAT con permiso "Contents: Read and write" acotado
 * a este repo — vive embebido en el bundle público de la app, es el trade-off aceptado por Lucas
 * frente a depender de otra plataforma) — no bloquea ni rompe el copiado al portapapeles. */
function sendVideoMetadataToGithub(title: string, description: string): void {
  const token = import.meta.env.VITE_GITHUB_METADATA_TOKEN as string | undefined
  if (!token) {
    return
  }

  const path = `data/youtube/video-metadata/${selectedDate.value}.json`
  const content = toBase64Utf8(JSON.stringify({ title, description, generatedAt: new Date().toISOString() }, null, 2))

  void fetch(`https://api.github.com/repos/${GITHUB_METADATA_REPO}/contents/${path}`, {
    method: 'PUT',
    headers: {
      Authorization: `Bearer ${token}`,
      Accept: 'application/vnd.github+json',
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      message: `feat: metadata de vídeo ${selectedDate.value}`,
      content,
      branch: GITHUB_METADATA_BRANCH,
    }),
  }).catch(() => {
    // Sin conexión o falla la API: el título+descripción siguen disponibles en el portapapeles.
  })
}

async function copyToClipboard(text: string): Promise<void> {
  try {
    if (navigator.clipboard?.writeText && window.isSecureContext) {
      await navigator.clipboard.writeText(text)
      return
    }
  } catch {
    // Fall through to broader compatibility path.
  }

  fallbackCopyText(text)
}

/** Copia título y descripción por separado (no concatenados), uno un segundo después del
 * otro: el portapapeles múltiple de Android guarda el historial de copias, así que Lucas puede
 * pegar cualquiera de los dos donde toque (título y descripción van en campos distintos en
 * YouTube). Pedido explícito de Lucas — antes iban juntos en un solo texto con "\n\n". */
async function copyAutoScrollClipboardText(): Promise<void> {
  const title = buildAutoScrollClipboardText()
  const description = buildVideoDescription()

  sendVideoMetadataToGithub(title, description)

  await copyToClipboard(title)

  if (description) {
    window.setTimeout(() => {
      void copyToClipboard(description)
    }, 1000)
  }
}

function translateRank(rank?: string): string {
