async function refreshPrayer(): Promise<void> {
  const version = ++loadVersion
  const requestDate = selectedDateObject.value
  const requestHour = activeHour.value
  isLoading.value = true
  error.value = ''

  try {
    const result = await loadPrayer(requestDate, requestHour)
    if (version === loadVersion) {
      loaded.value = result
      resolvePrayerOptionSelection()
      maybeShowSolemnityLordPrayerPrompt()
    }
  } catch (unknownError) {
    if (version !== loadVersion) return
    // La liturgia se calcula en local, así que aquí sólo se llega por un fallo del propio
    // cálculo... o porque el trozo de la librería aún no está descargado (primerísima visita
    // sin conexión). En ningún caso se enseña el mensaje crudo del navegador, que viene en
    // inglés: hasta el 05/09/2026 esto pintaba en pantalla un "Failed to fetch" a Lucas.
    error.value = mensajeDeRed(
      unknownError,
      'No se pudo preparar esta oración. Prueba con otro día o con otra Hora.',
      'Sin conexión: esta es la primera vez que abres la app sin red y aún no se ha guardado el texto de la liturgia. Conéctate una vez y quedará disponible sin conexión para siempre.',
    )
    showPrayerOptionPrompt.value = false
    loaded.value = null
  } finally {
    if (version === loadVersion) {
      isLoading.value = false
    }
  }
}

