function maybeShowSolemnityLordPrayerPrompt(): boolean {
  if (
    screen.value !== 'reader' ||
    showPrayerOptionPrompt.value ||
    showSolemnityLordPrayerPrompt.value ||
    !shouldAskLordPrayerForHour(activeHour.value)
  ) {
    return false
  }

  pendingSolemnityHour.value = activeHour.value
  showSolemnityLordPrayerPrompt.value = true
  return true
}

function enterHour(hour: HourKey): void {
  activeHour.value = hour
  if (screen.value !== 'reader') {
    pushHistoryScreen('reader')
  }
  screen.value = 'reader'
  stopScrollAndVideo()
  void nextTick(() => {
    window.scrollTo({ top: 0, behavior: 'auto' })
    autoScrollActive.value = autoScrollOnOpen.value
  })
}

function openHour(hour: HourKey): void {
  enterHour(hour)
}

function chooseSolemnityLordPrayer(language: LordPrayerLanguage): void {
  const hour = pendingSolemnityHour.value
  lordPrayerLanguage.value = language
  showSolemnityLordPrayerPrompt.value = false
  pendingSolemnityHour.value = null

  if (hour) {
    enterHour(hour)
  }
}

function toggleAutoScroll(): void {
  if (autoScrollActive.value) {
    stopScrollOnly()
    return
  }

  if (isWindowAtBottom()) {
    void copyAutoScrollClipboardText()
    return
  }

  shouldDelayNextAutoScrollStart = isWindowAtTop()
  autoScrollActive.value = true
}

function updateAutoScroll(): void {
  const delayStart = shouldDelayNextAutoScrollStart
  shouldDelayNextAutoScrollStart = false

  stopAutoScroll()

  if (screen.value === 'reader' && autoScrollActive.value) {
    if (delayStart) {
      autoScrollStartDelayTimer = window.setTimeout(() => {
        autoScrollStartDelayTimer = 0
        if (screen.value === 'reader' && autoScrollActive.value) {
          autoScrollFrame = requestAnimationFrame(scrollStep)
        }
      }, AUTO_SCROLL_TOP_DELAY_MS)
      return
    }

    autoScrollFrame = requestAnimationFrame(scrollStep)
  }
}

function stopAutoScroll(): void {
  if (autoScrollStartDelayTimer) {
    window.clearTimeout(autoScrollStartDelayTimer)
  }
  if (autoScrollFrame) {
    cancelAnimationFrame(autoScrollFrame)
  }
  autoScrollStartDelayTimer = 0
  autoScrollFrame = 0
  lastScrollTime = 0
  pendingScrollPixels = 0
  currentAutoScrollSpeed = autoScrollSpeed.value
}

/** Pantalla completa mientras se graba (Lucas, 05/09/2026): el vídeo del canal se graba con el
 * grabador de pantalla del móvil, y la barra de navegación del sistema salía dentro del vídeo.
 *
 * Lo que Lucas preguntó —que la app cambie sola a navegación por gestos y luego devuelva los
 * tres botones— NO puede hacerlo ninguna app: el modo de navegación vive en `Settings.Secure`
 * y escribirlo exige `WRITE_SECURE_SETTINGS`, reservado a apps de sistema (a una de terceros
 * solo se le concede a mano por `adb`), y desde la web ni siquiera existe esa superficie.
 *
 * Lo que sí se puede, y da el mismo resultado en el vídeo, es el modo inmersivo: en pantalla
 * completa Android oculta la barra de navegación esté en gestos o en tres botones, y al salir
 * la devuelve tal y como estaba, sin tocar ningún ajuste del sistema. */
async function enterImmersiveFullscreen(): Promise<void> {
  const root = document.documentElement

  if (document.fullscreenElement || !root.requestFullscreen) {
    return
  }

  try {
    await root.requestFullscreen({ navigationUI: 'hide' })
  } catch {
    // Safari de iPhone no lo implementa y el navegador puede negarlo si no cuenta el toque como
    // gesto de usuario: que no haya inmersivo nunca debe impedir la grabación.
  }
}

async function exitImmersiveFullscreen(): Promise<void> {
  if (!document.fullscreenElement || !document.exitFullscreen) {
    return
  }

  try {
    await document.exitFullscreen()
  } catch {
    // Si el propio Lucas ya salió deslizando desde el borde, no hay nada que deshacer.
  }
}

/** Para SOLO el scroll. No sale del inmersivo (10/09/2026): esto también se llama al llegar
 * abajo del todo, y salir ahí de pantalla completa cambiaba el alto del viewport — el
 * padding-bottom en vh de .reader-surface encogía, el documento se acortaba y el navegador
 * recolocaba el scroll de golpe hacia arriba: el "trompicón" final del vídeo. Además devolvía
 * la barra de navegación en los segundos que Lucas sigue grabando tras el "amén". El inmersivo
 * se deja en las paradas de la GRABACIÓN: stopScrollAndVideo y el finally de recordPrayerVideo. */
function stopScrollOnly(): void {
  autoScrollActive.value = false
  stopAutoScroll()
}

function cancelPrayerVideoExport(): void {
  videoExportAbort?.abort()
  videoExportAbort = null
  void stopNativeRecordingIfActive()
}

/** Cierra la burbuja de cámara del APK si está activa: suelta la cámara. Cubre TODOS los caminos de salida (toque para
 * parar, cambio de Hora, botón atrás), igual que el finally de exportPrayerVideo para la web. */
async function stopNativeRecordingIfActive(): Promise<void> {
  if (!nativeRecordingActive) return
  nativeRecordingActive = false
  nativeCameraStream?.getTracks().forEach((track) => track.stop())
  nativeCameraStream = null
  hasCameraPreview.value = false
  if (cameraPreviewVideo.value) {
    cameraPreviewVideo.value.srcObject = null
  }
  videoExportStatus.value = ''
  isExportingVideo.value = false
}

/** Variante del botón de cámara dentro del APK (29/09/2026, a petición de Lucas): solo pone la
 * burbuja con la cámara frontal y arranca el scroll. La pantalla y el audio los graba Lucas con el
 * grabador del móvil; la burbuja queda dentro de esa grabación. Antes arrancaba aquí el grabador
 * de pantalla nativo (plugin de Capgo) y, al fallar este, la cámara ni llegaba a abrirse. Tampoco
 * se usa exportPrayerVideo: dentro de la WebView el webm no se puede descargar. */
async function recordWithCameraBubbleOnly(): Promise<void> {
  isExportingVideo.value = true
  nativeRecordingActive = true
  videoExportStatus.value = ''

  try {
    nativeCameraStream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } })
  } catch {
    nativeCameraStream = null
  }
  if (nativeCameraStream && nativeRecordingActive) {
    hasCameraPreview.value = true
    await nextTick()
    if (cameraPreviewVideo.value) {
      cameraPreviewVideo.value.srcObject = nativeCameraStream
    }
  }

  if (!nativeRecordingActive) return
  shouldDelayNextAutoScrollStart = isWindowAtTop()
  autoScrollActive.value = true
}

/** Cambiar de Hora/pantalla: para el scroll Y corta cualquier grabación en curso (no debe
 * seguir con la cámara activa en segundo plano al salir de la pantalla). No copia ni manda nada
 * a GitHub — eso es solo cuando Lucas detiene la grabación él mismo, ver stopScrollAndCopy. */
function stopScrollAndVideo(): void {
  stopScrollOnly()
  cancelPrayerVideoExport()
  void exitImmersiveFullscreen()
}

/** Doble toque en la bolita (o en la burbuja de cámara, o click de nuevo en el botón mientras
 * graba): detener el scroll/grabación y copiar título+descripción al portapapeles. Antes esto
 * se disparaba solo al llegar abajo del todo, pero eso llegaba demasiado pronto — Lucas sigue
 * grabando con la pantalla nativa unos segundos más tras el "amén" final, o con la cámara hasta
 * que él mismo la detiene; el fin del scroll, por sí solo, no debe tocar la grabación. */
function stopScrollAndCopy(): void {
  stopScrollAndVideo()
  void copyAutoScrollClipboardText()
}

function handlePrimaryScrollButtonClick(): void {
  if (cameraScrollEnabled.value) {
    // Solo al ARRANCAR: si ya está grabando, este mismo toque es el de detener y de ahí sale
    // el exitImmersiveFullscreen de stopScrollAndVideo. Y va aquí, síncrono dentro del click, para
    // que el navegador lo cuente como gesto de usuario (dentro del async ya no valdría).
    if (!isExportingVideo.value) {
      void enterImmersiveFullscreen()
    }

    void recordPrayerVideo()
    return
  }

  toggleAutoScroll()
}

function handleScrollButtonDblClick(): void {
  // En modo cámara, el doble toque real para detener queda en la burbuja de vídeo (que tapa
  // el botón mientras graba) — ver el elemento .camera-preview-bubble en el template.
  if (cameraScrollEnabled.value) return
  stopScrollAndCopy()
}

/** Graba (con cámara frontal si el navegador la concede) mientras dura el auto-scroll de la
 * sección activa. Alternativa a la grabación de pantalla nativa, para cuando Lucas prefiere
 * que la app componga el vídeo directamente. Un segundo toque mientras graba detiene todo. */
async function recordPrayerVideo(): Promise<void> {
  if (isExportingVideo.value) {
    stopScrollAndCopy()
    return
  }

  if (Capacitor.isNativePlatform()) {
    await recordWithCameraBubbleOnly()
    return
  }

  const source = document.querySelector<HTMLElement>('.reader-surface')
  if (!source) return

  shouldDelayNextAutoScrollStart = isWindowAtTop()
  autoScrollActive.value = true

  let cameraStream: MediaStream | null = null
  try {
    // Solo vídeo, sin audio: el micrófono lo usa el grabador de pantalla nativo (que graba
    // aparte), y reservarlo aquí también se lo bloqueaba -- "micrófono ya en uso" al intentar
    // grabar con el nativo mientras la burbuja de cámara sigue activa. Pedido explícito de
    // Lucas (30/08/2026). El vídeo que compone la app queda mudo a propósito.
    cameraStream = await navigator.mediaDevices.getUserMedia({
      video: { facingMode: 'user' },
    })
  } catch {
    // Sin cámara (denegada, sin hardware, HTTP en LAN...): seguimos sin burbuja de cámara.
    cameraStream = null
  }

  isExportingVideo.value = true
  videoExportStatus.value = cameraStream ? 'Generando vídeo con cámara…' : 'Generando vídeo…'
  videoExportAbort = new AbortController()

  // Vista previa en vivo: la burbuja que compone exportPrayerVideo queda DENTRO del vídeo
  // grabado (no se ve en pantalla hasta descargarlo, y una Hora entera tarda varios minutos
  // en grabarse) — esto es solo para que Lucas vea al instante que la cámara está activa.
  if (cameraStream) {
    hasCameraPreview.value = true
    await nextTick()
    if (cameraPreviewVideo.value) {
      cameraPreviewVideo.value.srcObject = cameraStream
    }
  }

  try {
    const blob = await exportPrayerVideo(source, {
      cameraStream,
      liturgicalColor: liturgicalColor.value,
      readerScale: readerScale.value,
      signal: videoExportAbort.signal,
      speedPixelsPerSecond: autoScrollSpeed.value * AUTO_SCROLL_PIXELS_PER_UNIT,
      theme: 'default',
      onRecordingStarted: () => {
        videoExportStatus.value = 'Grabando…'
      },
    })

    if (blob) {
      downloadBlob(blob, `${activeHour.value}-${selectedDate.value}.webm`)
      videoExportStatus.value = ''
    } else {
      videoExportStatus.value = ''
    }
  } catch (exportError) {
    void exportError
    videoExportStatus.value = 'No se pudo generar el vídeo.'
    window.setTimeout(() => { videoExportStatus.value = '' }, 4000)
  } finally {
    isExportingVideo.value = false
    videoExportAbort = null
    hasCameraPreview.value = false
    if (cameraPreviewVideo.value) {
      cameraPreviewVideo.value.srcObject = null
    }
    stopScrollOnly()
    void exitImmersiveFullscreen()
  }
}

function downloadBlob(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = filename
  document.body.appendChild(link)
  link.click()
  link.remove()
  URL.revokeObjectURL(url)
}

function handlePopState(event: PopStateEvent): void {
  const historyState = (event.state ?? null) as HistoryScreenState | null
  const nextScreen = getHistoryScreen(historyState)

  stopScrollAndVideo()
  screen.value = nextScreen
  // La posición dentro de la Biblia va en el propio estado del historial, no en un
  // ref aparte: al volver atrás hay que restaurar el libro y el capítulo de esa
  // entrada, no los últimos que se estuvieran mirando.
  bibleBook.value = nextScreen === 'bible' ? historyState?.oranteBibleBook ?? null : null
  bibleChapter.value = nextScreen === 'bible' ? historyState?.oranteBibleChapter ?? null : null
  void nextTick(() => window.scrollTo({ top: 0, behavior: 'auto' }))
}

function getHistoryScreen(state: unknown): Screen {
  const historyState = state as HistoryScreenState | null
  if (historyState?.oranteScreen === 'reader') {
    return 'reader'
  }
  return historyState?.oranteScreen === 'bible' ? 'bible' : 'home'
}

function replaceHistoryScreen(nextScreen: Screen): void {
  const currentState = (window.history.state as HistoryScreenState | null) ?? {}
  window.history.replaceState({ ...currentState, ...historyScreenState(nextScreen) }, '')
}

function pushHistoryScreen(nextScreen: Screen): void {
  const currentState = (window.history.state as HistoryScreenState | null) ?? {}
  window.history.pushState({ ...currentState, ...historyScreenState(nextScreen) }, '')
}

function historyScreenState(nextScreen: Screen): HistoryScreenState {
  return {
    oranteScreen: nextScreen,
    oranteBibleBook: nextScreen === 'bible' ? bibleBook.value : null,
    oranteBibleChapter: nextScreen === 'bible' ? bibleChapter.value : null,
  }
}

/** Abre la Biblia por su índice de libros. */
function openBible(): void {
  bibleBook.value = null
  bibleChapter.value = null
  stopScrollAndVideo()
  pushHistoryScreen('bible')
  screen.value = 'bible'
  void nextTick(() => window.scrollTo({ top: 0, behavior: 'auto' }))
}

function openBibleBook(book: string): void {
  bibleBook.value = book
  bibleChapter.value = null
  pushHistoryScreen('bible')
}

function openBibleChapter(chapter: string): void {
  bibleChapter.value = chapter
  pushHistoryScreen('bible')
}

/** Botón "volver" de la pantalla de la Biblia: delega en el historial, para que la
 * flecha en pantalla y el botón físico de Android hagan exactamente lo mismo. */
function goBack(): void {
  window.history.back()
}

function isWindowAtTop(): boolean {
  return window.scrollY <= 1
}

function isWindowAtBottom(): boolean {
  return window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 3
}

function normalizedScrollSectionTitle(value: string): string {
  return value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
}

function prayerSectionTop(section: HTMLElement): number {
  return window.scrollY + section.getBoundingClientRect().top
}

function readerPrayerSectionByTitle(title: string): HTMLElement | undefined {
  const normalizedTitle = normalizedScrollSectionTitle(title)
  const sections = Array.from(document.querySelectorAll<HTMLElement>('.reader-surface .prayer-section'))

  return sections.find((section) => normalizedScrollSectionTitle(section.dataset.sectionTitle ?? '') === normalizedTitle)
}

/** Punto donde empieza cada tramo de la curva, con el factor que le corresponde -- ver el
 * comentario junto a AUTO_SCROLL_PHASE_START_FACTOR. Si la Hora no tiene esta estructura
 * completa (Lectura breve + Preces + Padrenuestro -- solo Laudes/Vísperas la tienen; el resto de
 * Horas no), no hay curva que aplicar: velocidad normal siempre, igual que antes de este cambio. */
function autoScrollPhaseFactor(): number {
  const lecturaBreve = readerPrayerSectionByTitle('Lectura breve')
  const preces = readerPrayerSectionByTitle('Preces')
  const padrenuestro = readerPrayerSectionByTitle('Padrenuestro')

  if (!lecturaBreve || !preces || !padrenuestro) {
    return AUTO_SCROLL_PHASE_NORMAL_FACTOR
  }

  const probeTop = window.scrollY + AUTO_SCROLL_SECTION_PROBE_PX

  if (probeTop < prayerSectionTop(lecturaBreve)) {
    return AUTO_SCROLL_PHASE_START_FACTOR
  }
  if (probeTop >= prayerSectionTop(preces) && probeTop < prayerSectionTop(padrenuestro)) {
    return AUTO_SCROLL_PHASE_PRECES_FACTOR
  }
  if (probeTop >= prayerSectionTop(padrenuestro)) {
    return AUTO_SCROLL_PHASE_AFTER_PRECES_FACTOR
  }

  return AUTO_SCROLL_PHASE_NORMAL_FACTOR
}

function autoScrollTargetSpeed(): number {
  return autoScrollSpeed.value * autoScrollPhaseFactor()
}

function moveToward(value: number, target: number, maximumDelta: number): number {
  if (value < target) {
    return Math.min(target, value + maximumDelta)
  }

  if (value > target) {
    return Math.max(target, value - maximumDelta)
  }

  return value
}

function scrollStep(timestamp: number): void {
  if (screen.value !== 'reader' || !autoScrollActive.value) {
    stopAutoScroll()
    return
  }

  if (!lastScrollTime) {
    lastScrollTime = timestamp
  }

  const elapsedSeconds = (timestamp - lastScrollTime) / 1000
  lastScrollTime = timestamp
  currentAutoScrollSpeed = moveToward(
    currentAutoScrollSpeed,
    autoScrollTargetSpeed(),
    AUTO_SCROLL_SPEED_TRANSITION_RATE * elapsedSeconds,
  )
  pendingScrollPixels += currentAutoScrollSpeed * AUTO_SCROLL_PIXELS_PER_UNIT * elapsedSeconds

  const scrollPixels = Math.trunc(pendingScrollPixels)
  if (scrollPixels > 0) {
    window.scrollBy({ top: scrollPixels, behavior: 'auto' })
    pendingScrollPixels -= scrollPixels
  }

  const atBottom = isWindowAtBottom()
  if (atBottom) {
    stopScrollOnly()
    return
  }

  autoScrollFrame = requestAnimationFrame(scrollStep)
}
</script>

