              </div>

              <div class="setting-group">
                <label>Velocidad de desplazamiento</label>
                <div class="scroll-speed-control">
                  <input
                    id="auto-scroll-speed"
                    v-model.number="autoScrollPresetIndex"
                    type="range"
                    min="0"
                    :max="AUTO_SCROLL_PRESETS.length - 1"
                    step="1"
                    aria-label="Velocidad de desplazamiento"
                    :aria-valuetext="`${currentAutoScrollPreset.label}: ${currentAutoScrollPreset.description}`"
                  />
                  <div class="scroll-speed-labels">
                    <button
                      v-for="(preset, index) in AUTO_SCROLL_PRESETS"
                      :key="preset.key"
                      type="button"
                      class="scroll-speed-option"
                      :class="{ active: preset.speed === autoScrollSpeed }"
                      :aria-pressed="preset.speed === autoScrollSpeed"
                      @click="setAutoScrollPreset(index)"
                    >
                      <!-- Solo el rótulo: la descripción ("Canto", "Lectura en voz alta"...) sigue
                           viva en aria-valuetext del deslizador, pero fuera de la pantalla. -->
                      <strong>{{ preset.label }}</strong>
                    </button>
                  </div>
                </div>
              </div>
            </section>

            <GuitarTuner />
          </aside>
        </div>
      </template>

      <template v-else-if="screen === 'bible'">
        <BiblePage
          :book="bibleBook"
          :chapter="bibleChapter"
          @select-book="openBibleBook"
          @select-chapter="openBibleChapter"
          @back="goBack"
        />
      </template>

      <template v-else>
        <article class="reader-surface">
          <div class="reader-header">
            <div>
              <p v-if="currentInfo?.celebration" class="reader-celebration">
                <span class="reader-celebration-dot" aria-hidden="true" />
                <span class="reader-celebration-text">{{ currentInfo.celebration }}</span>
                <span class="reader-celebration-dot" aria-hidden="true" />
              </p>
              <h1>{{ hourNames[activeHour] }}</h1>
              <p class="reader-date">{{ capitalizeFirst(formatLongDate(selectedDateObject)) }}</p>
            </div>
          </div>

          <div v-if="activeHour === 'officium'" class="reader-inline-controls">
            <select v-if="activeHour === 'officium'" v-model="officeTrack">
              <option value="a">Anual</option>
              <option value="i">Impar</option>
              <option value="p">Par</option>
            </select>
          </div>

          <div
            v-if="showPrayerOptionPrompt && loaded?.options.length"
            class="option-choice-backdrop"
            role="dialog"
            aria-label="Elección de opción litúrgica"
            aria-live="polite"
          >
            <div class="option-choice-modal">
              <p class="kicker">Hoy hay opciones</p>
              <h2>¿Qué quieres recitar?</h2>
              <p class="option-choice-subtitle">Selecciona la opción de esta fecha.</p>
              <div class="option-choice-grid">
                <button
                  v-for="(option, index) in loaded.options"
                  :key="`${option.id}-${index}`"
                  type="button"
                  class="option-choice-item"
                  @click="selectPrayerOption(index)"
                >
                  {{ optionTitle(option, index) }}
                </button>
              </div>
            </div>
          </div>

          <div v-if="isLoading" class="loading-state">
            <span />
            Cargando oración
          </div>

          <div v-else-if="error" class="empty-state">
            {{ error }}
          </div>

          <div v-else-if="!sections.length" class="empty-state">
            No hay contenido disponible para esta hora.
          </div>

          <template v-else>
            <PrayerSection
              v-for="(section, index) in sections"
              :key="`${section.title}-${section.eyebrow}`"
              :section="section"
              :alternative-index="alternativeIndexForSection(section)"
              :notation-enabled="singingNotation"
              :notation-mode="notationModeForSection(section, index)"
              :chant-picker-enabled="activeHour === 'laudes'"
              :posture-instructions-enabled="postureInstructionsEnabled"
              :capo-offset="capoOffsetForSection(section)"
              :inherited-capo-offset="inheritedCapoOffsetForSection(section)"
              :chant-key="chantKeyForSection(section)"
              :taken-chant-keys="takenChantKeysForSection(section)"
              @update:alternative-index="setAlternativeIndexForSection(section, $event)"
              @update:notation-mode="setNotationModeForSection(section, index, $event)"
              @chant-selected="setChantSelectionForSection(section, $event)"
              @capo-cycled="propagateCapoOffset(index, $event)"
            />
          </template>
        </article>

        <button
          type="button"
          class="floating-scroll-button floating-video-button"
          :class="{ active: cameraScrollEnabled ? isExportingVideo : autoScrollActive }"
          :aria-label="cameraScrollEnabled
            ? (isExportingVideo ? 'Cancelar grabación y scroll' : 'Grabar vídeo y hacer scroll')
            : (autoScrollActive ? 'Pausar scroll' : 'Iniciar scroll')"
          @click="handlePrimaryScrollButtonClick"
          @dblclick="handleScrollButtonDblClick"
        >
          <Video v-if="cameraScrollEnabled" :size="18" />
          <Pause v-else-if="autoScrollActive" :size="18" />
          <Play v-else :size="18" />
        </button>

        <video
          ref="cameraPreviewVideo"
          v-show="hasCameraPreview"
          class="camera-preview-bubble"
          autoplay
          muted
          playsinline
          @dblclick="stopScrollAndCopy"
        />
      </template>
    </main>

    <div
      v-if="showSolemnityLordPrayerPrompt"
      class="option-choice-backdrop"
      role="dialog"
      aria-label="Padrenuestro en solemnidad"
      aria-live="polite"
    >
      <div class="option-choice-modal">
        <p class="kicker">Solemnidad elegida</p>
        <h2>¿Padrenuestro en latín?</h2>
        <p class="option-choice-subtitle">
          Esta opción es solemnidad; elige cómo quieres rezar el Padrenuestro.
        </p>
        <div class="option-choice-grid option-choice-grid-two">
          <button type="button" class="option-choice-item" @click="chooseSolemnityLordPrayer('es')">
            Español
          </button>
          <button type="button" class="option-choice-item" @click="chooseSolemnityLordPrayer('la')">
            Latín
          </button>
        </div>
      </div>
    </div>
  </div>
</template>
