<script setup lang="ts">
import { computed, onBeforeUnmount, ref } from 'vue'
import { Guitar } from '@lucide/vue'
import { Capacitor } from '@capacitor/core'
import { detectPitch, GUITAR_STRINGS, IN_TUNE_CENTS, matchGuitarString } from '../lib/pitch'
import { micErrorMessage } from '../lib/mic-error'

/**
 * Afinador de guitarra de la pantalla de inicio. Vive apagado: sólo se ve el interruptor, y el
 * micrófono no se toca hasta que Lucas lo enciende a propósito.
 *
 * Se apaga solo al salir de la pantalla de inicio, porque App.vue destruye el `home` entero al
 * entrar en una Hora (`onBeforeUnmount` libera el micro). Eso importa de verdad: en Android dos
 * capturas de audio no conviven, y un afinador olvidado dejaría muda la grabación del vídeo.
 */

/** Cada cuánto se analiza el micrófono. Bastante más lento que un rAF por fotograma: el ojo no
 * distingue más de ~15 lecturas por segundo en una aguja y así el móvil no se calienta. */
const ANALYSIS_INTERVAL_MS = 70
/** La aguja recorre ±50 cents (medio semitono a cada lado); más allá se queda en el tope. */
const NEEDLE_RANGE_CENTS = 50
/** Sin lecturas válidas durante este tiempo se vuelve a "pulsa una cuerda". */
const SILENCE_TIMEOUT_MS = 1200
/** Suavizado exponencial de la frecuencia: quita el temblor de la aguja sin retrasarla. */
const SMOOTHING = 0.35

const active = ref(false)
const error = ref('')
const frequency = ref<number | null>(null)

let audioContext: AudioContext | null = null
let micStream: MediaStream | null = null
let analyser: AnalyserNode | null = null
let sourceNode: MediaStreamAudioSourceNode | null = null
let timer: number | null = null
let buffer: Float32Array | null = null
let smoothed: number | null = null
let lastReadingAt = 0

const match = computed(() => (frequency.value === null ? null : matchGuitarString(frequency.value)))
const cents = computed(() => (match.value ? Math.round(match.value.cents) : 0))
const isInTune = computed(() => match.value !== null && Math.abs(match.value.cents) <= IN_TUNE_CENTS)

/** Posición de la aguja en porcentaje del carril (50 % = afinado). */
const needleOffset = computed(() => {
  if (!match.value) return 50
  const clamped = Math.max(-NEEDLE_RANGE_CENTS, Math.min(NEEDLE_RANGE_CENTS, match.value.cents))
  return 50 + (clamped / NEEDLE_RANGE_CENTS) * 50
})

// Sin instrucciones de "tensa/afloja": lo dicen ya la aguja y los cents, y a Lucas le sobraban
// (06/09/2026). Fuera de tono el renglón se queda solo con el número; la altura la fija el CSS
// (.tuner-hint tiene min-height) para que la caja no dé un salto al cambiar de estado.
const hint = computed(() => {
  if (error.value) return error.value
  if (!match.value) return 'Pulsa una cuerda'
  if (isInTune.value) return 'Afinada'
  return ''
})

function toggle(): void {
  if (active.value) {
    stop()
  } else {
    void start()
  }
}

async function start(): Promise<void> {
  error.value = ''
  try {
    // Sin comprobar antes navigator.permissions: en el WebView del APK su estado no refleja el
    // permiso de Android ("solo mientras se usa la app" es un permiso concedido). Se intenta
    // abrir el micro siempre y se decide por el error real que devuelva.
    if (!navigator.mediaDevices?.getUserMedia) {
      throw Object.assign(new Error('mediaDevices no disponible'), { name: 'NoMediaDevices' })
    }
    // Sin los tres filtros de voz: el cancelador de eco y el control de ganancia deforman
    // justamente lo que aquí hay que medir (una nota sostenida es "ruido" para ellos).
    micStream = await navigator.mediaDevices.getUserMedia({
      audio: { autoGainControl: false, echoCancellation: false, noiseSuppression: false },
    })

    const AudioContextClass: typeof AudioContext =
      window.AudioContext ?? (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
    audioContext = new AudioContextClass()
    // En iOS el contexto nace suspendido aunque se cree dentro del gesto del toque.
    if (audioContext.state === 'suspended') await audioContext.resume()

    analyser = audioContext.createAnalyser()
    analyser.fftSize = 2048
    buffer = new Float32Array(analyser.fftSize)
    sourceNode = audioContext.createMediaStreamSource(micStream)
    sourceNode.connect(analyser)
    // El analizador no se conecta al destino a propósito: nada de devolver el micro por el
    // altavoz, que con la guitarra delante acopla al instante.

    active.value = true
    lastReadingAt = performance.now()
    timer = window.setInterval(analyse, ANALYSIS_INTERVAL_MS)
  } catch (startError) {
    // Cualquier fallo a media construcción deja el micro reservado si no se limpia aquí: el
    // permiso puede concederse y romperse el AudioContext justo después (ver la memoria
    // bug-microfono-getusermedia-sin-liberar).
    stop()
    console.warn('[afinador] getUserMedia falló', startError)
    error.value = micErrorMessage(startError, Capacitor.isNativePlatform())
  }
}

function stop(): void {
  if (timer !== null) {
    window.clearInterval(timer)
    timer = null
  }
  sourceNode?.disconnect()
  analyser?.disconnect()
  micStream?.getTracks().forEach((track) => track.stop())
  void audioContext?.close().catch(() => {})

  sourceNode = null
  analyser = null
  micStream = null
  audioContext = null
  buffer = null
  smoothed = null
  frequency.value = null
  active.value = false
}

function analyse(): void {
  if (!analyser || !buffer || !audioContext) return
  analyser.getFloatTimeDomainData(buffer)

  const reading = detectPitch(buffer, audioContext.sampleRate)
  const now = performance.now()

  if (!reading) {
    if (now - lastReadingAt > SILENCE_TIMEOUT_MS) {
      frequency.value = null
      smoothed = null
    }
    return
  }

  lastReadingAt = now
  // Al cambiar de cuerda el salto es grande y suavizarlo dejaría la aguja paseando por notas
  // que nadie ha tocado: por encima de un tono se salta directo a la lectura nueva.
  const isJump = smoothed === null || Math.abs(1200 * Math.log2(reading.frequency / smoothed)) > 200
  smoothed = isJump ? reading.frequency : smoothed + (reading.frequency - smoothed) * SMOOTHING
  frequency.value = smoothed
}

onBeforeUnmount(stop)
</script>

<template>
  <section class="tool-panel tuner-panel">
    <div class="panel-title panel-title-preces">
      <span class="panel-title-spacer" aria-hidden="true"></span>
      <div>
        <p class="home-date">Afinador</p>
      </div>
      <button
        type="button"
        class="tuner-power-button"
        :class="{ active }"
        :aria-pressed="active"
        :aria-label="active ? 'Apagar el afinador' : 'Encender el afinador'"
        @click="toggle"
      >
        <Guitar :size="16" />
      </button>
    </div>

    <div v-if="active" class="tuner-readout" :class="{ 'is-tuned': isInTune, 'is-idle': !match }">
      <p class="tuner-note">
        <template v-if="match">
          <strong>{{ match.string.latin }}</strong>
          <small>{{ match.string.name }} · {{ match.string.number }}ª</small>
        </template>
        <template v-else>
          <strong>—</strong>
        </template>
      </p>

      <div class="tuner-gauge" role="presentation">
        <span class="tuner-gauge-center" aria-hidden="true" />
        <span class="tuner-needle" :style="{ left: `${needleOffset}%` }" aria-hidden="true" />
      </div>

      <p class="tuner-hint" aria-live="polite">
        <span v-if="hint">{{ hint }}</span>
        <small v-if="match">{{ cents > 0 ? '+' : '' }}{{ cents }}</small>
      </p>

      <ul class="tuner-strings">
        <li
          v-for="string in GUITAR_STRINGS"
          :key="string.number"
          :class="{ active: match?.string.number === string.number, tuned: isInTune && match?.string.number === string.number }"
        >
          {{ string.name }}
        </li>
      </ul>
    </div>

    <p v-else-if="error" class="tuner-hint tuner-hint-error">{{ error }}</p>
  </section>
</template>
