export const CURATED_MASS_SONGS: Partial<Record<MassSongSectionKey, CuratedMassSong[]>> = {
  entrada: ENTRANCE_SONGS,
  meditacion: MEDITATION_SONGS,
}

export function curatedMassSongsFor(section: MassSongSectionKey): CuratedMassSong[] | undefined {
  return CURATED_MASS_SONGS[section]
}

/** Títulos de sección (los que ve App.vue en PrayerSectionData.title) que tienen catálogo
 * curado -- solo esas necesitan recordar cuál canto quedó elegido (ver
 * App.vue::alternativeIndexForSection/setAlternativeIndexForSection). Las secciones de canto
 * SIN catálogo curado siguen mostrando sugerencias genéricas sin nada que persistir. */
export const CURATED_MASS_SONG_TITLES = new Set(
  (Object.keys(CURATED_MASS_SONGS) as MassSongSectionKey[]).map(massSongTitle),
)

export function curatedMassSongContent(song: CuratedMassSong): string {
  // Pedido de Lucas (30/08/2026): quitar la línea "Fuente" de la vista -- sourceLabel/sourceUrl
  // se conservan en los datos (trazabilidad de dónde salió la letra) pero ya no se muestran.
  return ['<div class="mass-song">', renderChordSheet(song.chordSheet), '</div>'].join('')
}
