/** Título de sección (en Laudes) -> pool de melodías entre las que cicla el ChantPicker. */
export const LAUDES_CHANT_POOLS: Record<string, ChantVariant[]> = {
  'Invocación inicial': INVOCATION_CHANTS,
  Himno: HYMN_CHANTS,
  'Primer salmo': PSALM_CHANTS,
  'Segundo salmo': PSALM_CHANTS,
  'Tercer salmo': PSALM_CHANTS,
  'Responsorio breve': RESPONSORY_CHANTS,
  'Cántico de Zacarías': ZACHARY_CANTICLE_CHANTS,
  Padrenuestro: LORD_PRAYER_CHANTS,
}

/** Título de sección (en Laudes) -> key del cántico por defecto de ese día tipo. */
export const LAUDES_CHANT_DEFAULTS: Record<string, string> = {
  'Invocación inicial': 'invocacion',
  Himno: 'greg',
  'Primer salmo': 'tatotaton',
  'Segundo salmo': 'tatitaton',
  'Tercer salmo': 'ascendente',
  'Responsorio breve': 'responsorio',
  'Cántico de Zacarías': 'zacarias',
  Padrenuestro: 'padrenuestro',
}

export function chantVariant(sectionTitle: string, key: string): ChantVariant | undefined {
  return LAUDES_CHANT_POOLS[sectionTitle]?.find((chant) => chant.key === key)
}
