export interface PrayerVideoExportOptions {
  liturgicalColor: string
  readerScale: number
  signal?: AbortSignal
  speedPixelsPerSecond: number
  theme: string
  onRecordingStarted?: () => void
  /** Stream de la cámara frontal (ya obtenido con getUserMedia) para componerla como burbuja. */
  cameraStream?: MediaStream | null
}

const VIDEO_WIDTH = 1080
const VIDEO_HEIGHT = 1920
const VIDEO_FPS = 30
const STATIC_SECONDS = 1
const CAMERA_BUBBLE_DIAMETER = 300
const CAMERA_BUBBLE_MARGIN = 36
const CAMERA_BUBBLE_BORDER = 6

/** Envoltorio delgado: garantiza soltar la cámara/micrófono (options.cameraStream) pase lo que
 * pase dentro. La función interna solo los detiene desde su propio `stop()`, que se registra
 * DESPUÉS de renderElementToCanvas (html2canvas-pro sobre el contenido entero de la Hora, puede
 * tardar varios segundos) — si Lucas cancela mientras tanto, la función interna vuelve con
 * `return null` sin haber llegado a crear ese `stop()`, y el stream de getUserMedia quedaba
 * abierto para siempre (síntoma real: "micrófono ya en uso" al intentar grabar con el grabador
 * nativo después). Detener un track ya detenido no hace nada, así que este `finally` es una red
 * de seguridad incondicional, no un doble manejo. */
export async function exportPrayerVideo(source: HTMLElement, options: PrayerVideoExportOptions): Promise<Blob | null> {
  try {
    return await exportPrayerVideoInner(source, options)
  } finally {
    options.cameraStream?.getTracks().forEach((track) => track.stop())
  }
}

async function exportPrayerVideoInner(source: HTMLElement, options: PrayerVideoExportOptions): Promise<Blob | null> {
  if (!supportsCanvasRecording()) {
    throw new Error('Este navegador no puede generar video desde la app.')
  }

  const sourceWidth = Math.max(320, Math.ceil(source.getBoundingClientRect().width))
  const scale = VIDEO_WIDTH / sourceWidth
  const viewportHeight = VIDEO_HEIGHT / scale
  const contentHeight = Math.max(Math.ceil(source.scrollHeight), Math.ceil(viewportHeight))
  const image = await renderElementToCanvas(source, {
    contentHeight,
    liturgicalColor: options.liturgicalColor,
    readerScale: options.readerScale,
    theme: options.theme,
    width: sourceWidth,
  })

  if (options.signal?.aborted) {
    return null
  }

  const canvas = document.createElement('canvas')
  canvas.width = VIDEO_WIDTH
  canvas.height = VIDEO_HEIGHT
  const context = canvas.getContext('2d')

  if (!context) {
    throw new Error('No se pudo preparar el lienzo del video.')
  }

  const cameraVideo = options.cameraStream ? await prepareCameraVideoElement(options.cameraStream) : null

  const canvasStream = canvas.captureStream(VIDEO_FPS)
  const audioTracks = options.cameraStream?.getAudioTracks() ?? []
  const recordedStream = new MediaStream([...canvasStream.getVideoTracks(), ...audioTracks])
  const recorder = new MediaRecorder(recordedStream, recorderOptions(audioTracks.length > 0))
  const chunks: Blob[] = []
  let animationFrame = 0
  let startedAt = 0
  let stopped = false

  const maxOffset = Math.max(0, contentHeight - viewportHeight)
  const speed = Math.max(0, options.speedPixelsPerSecond)
  const movingSeconds = speed > 0 ? maxOffset / speed : 0
  const durationSeconds = STATIC_SECONDS + movingSeconds

  const stop = () => {
    if (stopped) return
    stopped = true
    if (animationFrame) {
      cancelAnimationFrame(animationFrame)
    }
    canvasStream.getTracks().forEach((track) => track.stop())
    options.cameraStream?.getTracks().forEach((track) => track.stop())
    cameraVideo?.remove()
    if (recorder.state !== 'inactive') {
      recorder.stop()
    }
  }

  options.signal?.addEventListener('abort', stop, { once: true })

  await new Promise<void>((resolve, reject) => {
    recorder.ondataavailable = (event) => {
      if (event.data.size > 0) {
        chunks.push(event.data)
      }
    }

    recorder.onerror = () => {
      stop()
      reject(new Error('No se pudo grabar el video generado.'))
    }

    recorder.onstop = () => {
      options.signal?.removeEventListener('abort', stop)
      resolve()
    }

    drawFrame(context, image, 0, sourceWidth, viewportHeight, cameraVideo, options.liturgicalColor)
    recorder.start(1000)
    options.onRecordingStarted?.()

    const tick = (timestamp: number) => {
      if (options.signal?.aborted) {
        stop()
        return
      }

      if (!startedAt) {
        startedAt = timestamp
      }

      const elapsedSeconds = (timestamp - startedAt) / 1000
      const movingElapsed = Math.max(0, elapsedSeconds - STATIC_SECONDS)
      const offset = Math.min(maxOffset, movingElapsed * speed)
      drawFrame(context, image, offset, sourceWidth, viewportHeight, cameraVideo, options.liturgicalColor)

      if (elapsedSeconds >= durationSeconds) {
        stop()
        return
      }

      animationFrame = requestAnimationFrame(tick)
    }

    animationFrame = requestAnimationFrame(tick)
  })

  if (!options.signal?.aborted && chunks.length) {
    return new Blob(chunks, { type: chunks[0]?.type || 'video/webm' })
  }

  return null
}

function supportsCanvasRecording(): boolean {
  return typeof MediaRecorder !== 'undefined' && typeof HTMLCanvasElement.prototype.captureStream === 'function'
}

function recorderOptions(withAudio: boolean): MediaRecorderOptions | undefined {
  const candidates = withAudio
    ? ['video/webm;codecs=vp9,opus', 'video/webm;codecs=vp8,opus', 'video/webm']
    : ['video/webm;codecs=vp9', 'video/webm']

  const mimeType = candidates.find((candidate) => MediaRecorder.isTypeSupported(candidate))
  return mimeType ? { mimeType } : undefined
}

async function prepareCameraVideoElement(stream: MediaStream): Promise<HTMLVideoElement> {
  const video = document.createElement('video')
  video.muted = true
  video.playsInline = true
  video.srcObject = stream
  await new Promise<void>((resolve, reject) => {
    video.onloadedmetadata = () => resolve()
    video.onerror = () => reject(new Error('No se pudo iniciar la cámara.'))
  })
  await video.play()
  return video
}

function drawFrame(
  context: CanvasRenderingContext2D,
  image: HTMLCanvasElement,
  offset: number,
  sourceWidth: number,
  viewportHeight: number,
  cameraVideo?: HTMLVideoElement | null,
  liturgicalColor?: string,
): void {
  context.fillStyle = '#22221c'
  context.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT)
  context.drawImage(image, 0, offset, sourceWidth, viewportHeight, 0, 0, VIDEO_WIDTH, VIDEO_HEIGHT)

  if (cameraVideo && cameraVideo.readyState >= cameraVideo.HAVE_CURRENT_DATA) {
    drawCameraBubble(context, cameraVideo, liturgicalColor || 'rgba(244, 239, 228, 0.92)')
  }
}

function drawCameraBubble(context: CanvasRenderingContext2D, cameraVideo: HTMLVideoElement, borderColor: string): void {
  const radius = CAMERA_BUBBLE_DIAMETER / 2
  const cx = VIDEO_WIDTH - CAMERA_BUBBLE_MARGIN - radius
  const cy = VIDEO_HEIGHT - CAMERA_BUBBLE_MARGIN - radius

  // Recorte "cover": la cámara suele venir en horizontal (16:9) y hay que llenar el círculo sin deformar.
  const videoWidth = cameraVideo.videoWidth || 1
  const videoHeight = cameraVideo.videoHeight || 1
  const videoScale = Math.max(CAMERA_BUBBLE_DIAMETER / videoWidth, CAMERA_BUBBLE_DIAMETER / videoHeight)
  const drawWidth = videoWidth * videoScale
  const drawHeight = videoHeight * videoScale

  context.save()
  context.beginPath()
  context.arc(cx, cy, radius, 0, Math.PI * 2)
  context.closePath()
  context.clip()
  // Espejado horizontal, como ve Lucas su propia cámara en pantalla.
  context.translate(cx, cy)
  context.scale(-1, 1)
  context.drawImage(cameraVideo, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight)
  context.restore()

  context.save()
  context.beginPath()
  context.arc(cx, cy, radius - CAMERA_BUBBLE_BORDER / 2, 0, Math.PI * 2)
  context.lineWidth = CAMERA_BUBBLE_BORDER
  context.strokeStyle = borderColor
  context.stroke()
  context.restore()
}

// NOTA: antes esto rasterizaba el contenido como imagen SVG con <foreignObject> HTML dentro
// (técnica típica de dom-to-image / html-to-image). Chrome MANCHA ("taints") el canvas al
// dibujar esa imagen — toBlob/getImageData/captureStream fallan o, en el caso de
// captureStream, simplemente no emiten ningún dato (silencioso, sin excepción). Por eso el
// vídeo nunca se generaba. html2canvas-pro dibuja el DOM con primitivas de canvas (sin pasar
// por una imagen SVG), así que el canvas resultante queda "limpio" y sí se puede grabar.
// -pro (no el html2canvas original) porque entiende color-mix()/oklch(), que usa este CSS.
async function renderElementToCanvas(
  source: HTMLElement,
  options: {
    contentHeight: number
    liturgicalColor: string
    readerScale: number
    theme: string
    width: number
  },
): Promise<HTMLCanvasElement> {
  const {default: html2canvas} = await import('html2canvas-pro')

  const clone = source.cloneNode(true) as HTMLElement
  clone.querySelectorAll('.reader-inline-controls').forEach((element) => element.remove())
  clone.querySelectorAll('.reader-header > svg').forEach((element) => element.remove())
  clone.style.border = '0'
  clone.style.borderRadius = '0'
  clone.style.boxShadow = 'none'
  clone.style.margin = '0'
  clone.style.overflow = 'visible'
  clone.style.width = `${options.width}px`
  clone.style.minHeight = `${options.contentHeight}px`

  const app = document.createElement('div')
  app.className = 'app'
  app.dataset.theme = options.theme
  app.style.setProperty('--reader-scale', String(options.readerScale))
  app.style.setProperty('--liturgical-color', options.liturgicalColor)
  app.style.width = `${options.width}px`
  app.style.minHeight = `${options.contentHeight}px`
  app.style.background = 'var(--surface)'

  const shell = document.createElement('main')
  shell.className = 'app-shell is-reader'
  shell.style.maxWidth = `${options.width}px`
  shell.style.padding = '0'
  shell.append(clone)
  app.append(shell)

  // html2canvas necesita el nodo con layout real (adjunto al documento), pero fuera de la
  // pantalla para no molestar mientras se graba.
  const offscreen = document.createElement('div')
  offscreen.style.position = 'fixed'
  offscreen.style.top = '0'
  offscreen.style.left = '-99999px'
  offscreen.style.width = `${options.width}px`
  offscreen.style.pointerEvents = 'none'
  offscreen.append(app)
  document.body.append(offscreen)

  try {
    return await html2canvas(app, {
      width: options.width,
      height: options.contentHeight,
      windowWidth: options.width,
      backgroundColor: null,
      useCORS: true,
      scale: 1,
    })
  } finally {
    offscreen.remove()
  }
}
