const scriptureCitationPattern = /^(?:[1-3]\s*)?[A-Za-zÁÉÍÓÚÜÑáéíóúüñ]{1,12}\.?\s*\d/

function scriptureReferenceLine(ref: string): string {
  const cleanRef = cleanSeasonalReadingRef(ref)
  const inlineCitation = [...cleanRef.matchAll(/\$\s*([^$\n\r]+)/g)]
    .map((match) => match[1].trim())
    .reverse()
    .find((line) => scriptureCitationPattern.test(line))

  if (inlineCitation) {
    return inlineCitation
  }

  const lines = stripInlineMarkers(cleanRef)
    .replace(/\r\n/g, '\n')
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean)
  const citationLine = [...lines]
    .reverse()
    .find((line) => scriptureCitationPattern.test(line))

  return citationLine ?? lines[0] ?? ''
}

function scriptureBookKey(ref: string): string {
  return scriptureReferenceLine(ref)
    .match(/^([1-3]?\s*[A-Za-zÁÉÍÓÚÜÑáéíóúüñ]+)/)?.[1]
    ?.replace(/\s+/g, '')
    .toLowerCase() ?? ''
}

