function scriptureBookName(ref: string): string {
  return scriptureBooks[scriptureBookKey(ref)] ?? ''
}

function scriptureReadingIntro(ref: string): string {
  const book = scriptureBookName(ref)

  if (!book) {
    return ''
  }

  if (
    book.startsWith('libro ') ||
    book.startsWith('primer libro ') ||
    book.startsWith('segundo libro ') ||
    book.startsWith('Cantar ')
  ) {
    return `Lectura del ${book}`
  }

  return `Lectura de la ${book}`
}

function stripInlineMarkers(value: string): string {
  return value
    .replace(/_([^_]+)_/g, '$1')
    .replace(/\$([^$]+)\$/g, '$1')
    .replace(/\$/g, '')
    .trim()
}

function readingEyebrow(ref: string): string {
  return readingCitation(ref)
}

function readingCitation(ref: string): string {
  const citation = scriptureReferenceLine(ref)
    .replace(/\s*:\s*.*$/s, '')
    .trim()

  const deduplicated = citation.replace(/^(.{4,})\1$/, '$1')

  return scriptureCitationPattern.test(deduplicated) ? deduplicated : ''
}

function asSentence(value: string): string {
  const trimmed = value.trim()

  return /[.!?]$/.test(trimmed) ? trimmed : `${trimmed}.`
}

function scriptureCaptionText(value?: string): string {
  const text = value?.trim() ?? ''
  const italic = text.match(/_([^_]+)_/)?.[1]?.trim()

  if (italic) {
    return italic
  }

  const afterCitation = text.match(/:\s*(.+)$/s)?.[1]?.trim()

  return afterCitation ? stripInlineMarkers(afterCitation) : ''
}

function massScriptureReadingContent(ref: string, text: string): string {
  const intro = scriptureReadingIntro(ref)
  const lectionaryReference = readingCitation(ref)
  const readingText = cleanReadingText(text)

  return [
    lectionaryReference ? `[[READING_REFERENCE]] ${lectionaryReference}` : '',
    intro ? `[[MASS_READING_PROCLAMATION]] ${asSentence(intro)}` : '',
    readingText,
    '$Lector.$ Palabra de Dios.',
    '$Pueblo.$ Te alabamos, Señor.',
  ]
    .filter(hasText)
    .join('\n\n')
}

function massAcclamationResponse(settings: PrayerBuildSettings): string {
  return settingHasSeason(settings, 'lent') ? '$Todos.$ Honor y gloria a ti, Señor Jesús.' : '$Todos.$ Aleluya.'
}

function massAcclamationVerse(ref: string, text: string, settings: PrayerBuildSettings): string {
  if (hasText(text)) {
    return text
  }

  return scriptureCaptionText(ref) || scriptureCaptionText(settings.massGospelReference) || stripInlineMarkers(ref)
}

function massAcclamationContent(ref: string, text: string, settings: PrayerBuildSettings): string {
  const settingsText = [settings.celebration, settings.rank, ...(settings.seasons ?? [])]
    .filter(Boolean)
    .join(' ')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
  const sequenceAsAcclamation = /secuencia/i.test(ref) && hasText(text)
  const verse = settingsText.includes('pentecost') && sequenceAsAcclamation
    ? 'Ven, Espíritu Santo, llena los corazones de tus fieles y enciende en ellos el fuego de tu amor.'
    : massAcclamationVerse(ref, text, settings)
  const response = massAcclamationResponse(settings)

  return [response, `$Cantor.$ ${verse}`, response].join('\n\n')
}

function choirSongSection(
  section: MassSongSectionKey,
  record: PrayerRecord,
  settings: PrayerBuildSettings,
): PrayerSection {
  // Cantos curados por Lucas (letra + acordes reales, elegibles y persistentes): reemplazan a
  // las sugerencias genéricas con enlace externo, sección por sección, según se van definiendo.
  // Ver mass-song-catalog.ts.
  const curated = curatedMassSongsFor(section)

  return {
    title: massSongTitle(section),
    alternatives: curated
      ? curated.map((song) => ({ label: song.title, content: curatedMassSongContent(song) }))
      : massSongAlternatives(section, record, settings),
    kind: 'mass',
    quiet: true,
  }
}

function seasonalReadingLabel(ref: string): string {
  return (
    ref.match(
      /^\s*\$?\s*((?:en\s+tiempo\s+pascual|tiempo\s+pascual|fuera\s+del\s+tiempo\s+pascual|fuera\s+de\s+pascua|no\s+pascua|si\s+no\s+es\s+pascua|pascua|si\s+es\s+pascua))\s*:/i,
    )?.[1] ?? ''
  )
}

function readingMatchesSeason(ref: string, seasons?: string[]): boolean {
  const label = seasonalReadingLabel(ref)

  if (!hasText(label)) {
    return true
  }

  if (isEasterSeasonLabel(label)) {
    return isEasterSeason(seasons)
  }

  if (isNonEasterSeasonLabel(label)) {
    return !isEasterSeason(seasons)
  }

  return true
}

function cleanSeasonalReadingRef(ref: string): string {
  return ref
    .replace(/^\s*\$?\s*(?:evangelio\s+pascual\s+para\s+el\s+ciclo\s+[ABC]|en\s+el\s+ciclo\s+[ABC])\s*:\s*/i, '')
    .replace(
      /^\s*\$?\s*(?:en\s+tiempo\s+pascual|tiempo\s+pascual|fuera\s+del\s+tiempo\s+pascual|fuera\s+de\s+pascua|no\s+pascua|si\s+no\s+es\s+pascua|pascua|si\s+es\s+pascua)\s*:\s*/i,
      '',
    )
    .trim()
}

function normalizeMassScriptureRef(ref: string, text: string): string {
  const cleanRef = cleanSeasonalReadingRef(ref)
  const normalizedText = text
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()

  if (/^Jn\s+11\b/i.test(cleanRef) && normalizedText.startsWith('queridos hermanos: este es el mensaje')) {
    return '1 Jn 1, 5 - 2, 2: _La sangre de Jesús nos limpia de todo pecado._'
  }

  if (
    /^Sal\s+102\b/i.test(cleanRef) &&
    normalizedText.startsWith('en aquel tiempo, tomo la palabra jesus y dijo')
  ) {
    return 'Mt 11, 25-30: _Has escondido estas cosas a los sabios y entendidos, y se las has revelado a la gente sencilla._'
  }

  if (
    /^1\s*Jn\s+1\b/i.test(cleanRef) &&
    normalizedText.startsWith('bendice, alma mia, al senor')
  ) {
    return 'Sal 102, 1b-2.3-4.8-9.13-14.17-18: _Bendice, alma mía, al Señor._'
  }

  return cleanRef
}

function isFirstReadingType(type: string): boolean {
  return type === 'FIRSTLECTURE' || type === 'CELEBRATION_FIRSTLECTURE'
}

function isSecondReadingType(type: string): boolean {
  return type === 'SECONDLECTURE' || type === 'CELEBRATION_SECONDLECTURE'
}

function massReadings(record: PrayerRecord, seasons?: string[]): PrayerRecord[] {
  const entries = asRecordArray(record.lecturas)
    .map((reading, index) => ({
      reading,
      index,
      order: massReadingTypeOrder.get(massReadingType(reading)) ?? Number.POSITIVE_INFINITY,
    }))
    .filter(
      ({ reading, order }) =>
        Number.isFinite(order) &&
        (hasText(asText(reading, 'ref')) || hasText(asText(reading, 'texto'))) &&
        readingMatchesSeason(asText(reading, 'ref'), seasons),
    )

  const hasFirstReading = entries.some(({ reading }) => isFirstReadingType(massReadingType(reading)))
  const celebrationEntries = entries.filter(({ reading }) => massReadingType(reading).startsWith('CELEBRATION_'))
  const hasCelebrationMassCore =
    celebrationEntries.some(({ reading }) => isFirstReadingType(massReadingType(reading))) &&
    celebrationEntries.some(({ reading }) => isMassGospelType(massReadingType(reading)))

  if (hasCelebrationMassCore) {
    return celebrationEntries
      .sort((left, right) => left.order - right.order || left.index - right.index)
      .map(({ reading }) => reading)
  }

  const celebrationOrders = new Set(
    entries
      .filter(({ reading }) => massReadingType(reading).startsWith('CELEBRATION_'))
      .map(({ reading }) => massReadingTypeOrder.get(massReadingType(reading))),
  )

  return entries
    .filter(({ reading }) => {
      const type = massReadingType(reading)
      const order = massReadingTypeOrder.get(type)

      return type.startsWith('CELEBRATION_') || !celebrationOrders.has(order)
    })
    .sort((left, right) => {
      const leftOrder = !hasFirstReading && isSecondReadingType(massReadingType(left.reading)) ? 10 : left.order
      const rightOrder = !hasFirstReading && isSecondReadingType(massReadingType(right.reading)) ? 10 : right.order

      return leftOrder - rightOrder || left.index - right.index
    })
    .map(({ reading }) => reading)
}

function preferredMassCycles(date: Date, info: LiturgyInformationOutput): string[] {
  const values: string[] = []
  const rank = info.rank?.toUpperCase()

  if (rank && rank !== 'WEEKDAY' && rank !== 'FERIA') {
    values.push('MEMORY')
  }

  if (info.cycle) {
    values.push(`YEAR_${info.cycle.toUpperCase()}`)
  }

  values.push(date.getFullYear() % 2 === 0 ? 'EVEN' : 'ODD')
  values.push('ANY', 'MEMORY')

  return [...new Set(values)]
}

