function localMassReadingOverrideOptions(date: Date): PrayerRecord[] {
  const key = `${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`

  return localMassReadingOverrides[key] ?? []
}

function massOptionInfo(info: LiturgyInformationOutput, celebration: string): LiturgyInformationOutput {
  return {
    ...info,
    color: 'WHITE',
    celebration,
    rank: 'SOLEMNITY',
  }
}

function splitHolyThursdayMassOptions(record: PrayerRecord, info: LiturgyInformationOutput): PrayerRecord[] | undefined {
  if (asText(record, 'id') !== 'holy_thursday') {
    return undefined
  }

  const readings = asRecordArray(record.lecturas)
  const eveningReadings = readings.filter((reading) => massReadingType(reading).startsWith('CELEBRATION_'))
  const chrismReadings = readings.filter((reading) => !massReadingType(reading).startsWith('CELEBRATION_'))
  const hasEveningMass =
    eveningReadings.some((reading) => isFirstReadingType(massReadingType(reading))) &&
    eveningReadings.some((reading) => isMassGospelType(massReadingType(reading)))
  const hasChrismMass =
    chrismReadings.some((reading) => isFirstReadingType(massReadingType(reading))) &&
    chrismReadings.some((reading) => isMassGospelType(massReadingType(reading)))

  if (!hasEveningMass || !hasChrismMass) {
    return undefined
  }

  return [
    withOptionMeta(
      { ...record, id: 'holy_thursday_evening_mass', lecturas: eveningReadings },
      'Misa vespertina de la Cena del Señor',
      massOptionInfo(info, 'Misa vespertina de la Cena del Señor'),
    ),
    withOptionMeta(
      { ...record, id: 'holy_thursday_chrism_mass', lecturas: chrismReadings },
      'Misa Crismal',
      massOptionInfo(info, 'Misa Crismal'),
    ),
  ]
}

function selectMassReadingOptions(
  readings: PrayerRecord[] | undefined,
  date: Date,
  info: LiturgyInformationOutput,
): PrayerRecord[] {
  const options = (readings ?? []).filter((record) => massReadings(record, info.seasons).length)

  if (!options.length) {
    return localMassReadingOverrideOptions(date)
  }

  const cycles = preferredMassCycles(date, info)

  for (let index = 0; index < cycles.length; index += 1) {
    const cycle = cycles[index]
    const matchingOptions = options.filter((record) => asText(record, 'cycle').toUpperCase() === cycle)

    if (!matchingOptions.length) {
      continue
    }

    const splitHolyThursday = matchingOptions.flatMap((record) => splitHolyThursdayMassOptions(record, info) ?? [record])
    const primaryOptions = splitHolyThursday.length !== matchingOptions.length ? splitHolyThursday : matchingOptions

    // Memoria libre (no fiesta ni solemnidad, ambas obligatorias): además de la Misa del
    // santo, se ofrece como alternativa elegible la Misa ferial — el celebrante puede optar
    // por cualquiera de las dos. Se busca en el resto de ciclos preferidos, en orden, la
    // primera lectura que no sea ya la del santo (nunca tiene cycle 'MEMORY').
    if (cycle === 'MEMORY' && info.rank?.toUpperCase() === 'MEMORIAL') {
      const ferialOption = cycles
        .slice(index + 1)
        .map((ferialCycle) => options.find((record) => asText(record, 'cycle').toUpperCase() === ferialCycle))
        .find((record): record is PrayerRecord => Boolean(record))

      if (ferialOption) {
        return [...primaryOptions, ferialOption]
      }
    }

    return primaryOptions
  }

  return options.flatMap((record) => splitHolyThursdayMassOptions(record, info) ?? [record])
}

function selectCycleText(value: string, cycle?: string): string {
  if (!hasText(value) || !cycle) {
    return value
  }

  const currentCycle = cycle.trim().toLowerCase()
  if (!['a', 'b', 'c'].includes(currentCycle)) {
    return value
  }

  // La etiqueta viene envuelta como rúbrica autocontenida: "$ Año A: $texto". El "$?" de
  // después de los dos puntos se come el "$" de CIERRE de esa rúbrica — si no, quedaba un
  // "$" suelto al principio del texto que se emparejaba sin querer con el próximo "$" de
  // otra rúbrica más adelante (p. ej. la de la señal de la cruz), rompiendo todo lo que
  // había entre medias.
  const marker = /^\s*\$?\s*Año\s*([ABC])\s*:\s*\$?\s*(.*)$/i
  const hasCycleLabels = /(^|\n)\s*\$?\s*Año\s*[ABC]\s*:/i.test(value)
  if (!hasCycleLabels) {
    return value
  }

  const lines = value.split(/\r?\n/)
  const parts = new Map<string, string[]>()
  let active: string | null = null

  for (const rawLine of lines) {
    const match = rawLine.match(marker)
    if (match) {
      active = match[1].toLowerCase()
      const text = (match[2] ?? '').trim()
      if (text.length) {
        parts.set(active, [text])
      } else {
        parts.set(active, [])
      }
      continue
    }

    if (active) {
      const existing = parts.get(active)
      if (existing) {
        existing.push(rawLine)
      }
    }
  }

  const selected = parts.get(currentCycle)
  if (!selected?.length) {
    return value
  }

  return selected.join('\n').trim()
}

function isEasterSeason(seasons?: string[]): boolean {
  return Boolean(
    seasons?.some((season) => {
      const value = season.toUpperCase()
      return value.includes('EASTER') || (value.includes('PASCHAL') && !value.includes('TRIDUUM'))
    }),
  )
}

function hasSeason(seasons: string[] | undefined, seasonName: string): boolean {
  return Boolean(seasons?.some((season) => season.toUpperCase().includes(seasonName)))
}

function isPaschalTriduum(seasons?: string[]): boolean {
  return hasSeason(seasons, 'PASCHAL_TRIDUUM')
}

function isEasterOctave(seasons?: string[]): boolean {
  return hasSeason(seasons, 'EASTER_OCTAVE')
}

function isEasterSeasonLabel(label: string): boolean {
  return /^(?:si\s+es\s+pascua|pascua|en\s+tiempo\s+pascual|tiempo\s+pascual)$/i.test(label.trim())
}

function isNonEasterSeasonLabel(label: string): boolean {
  return /^(?:si\s+no\s+es\s+pascua|no\s+pascua|fuera\s+de\s+pascua|fuera\s+del\s+tiempo\s+pascual)$/i.test(
    label.trim(),
  )
}

function selectInlineSeasonalText(value: string, seasons?: string[]): string {
  if (!hasText(value) || !seasons?.length) {
    return value
  }

  return value.replace(
    /\s*\$\(\s*((?:fuera\s+del\s+tiempo\s+pascual|fuera\s+de\s+pascua|no\s+pascua|si\s+no\s+es\s+pascua|en\s+tiempo\s+pascual|tiempo\s+pascual|pascua|si\s+es\s+pascua))\s*:\s*\$?\s*([\s\S]*?)\s*\$\)/gi,
    (_match, label: string, text: string) => {
      const shouldShow =
        (isEasterSeason(seasons) && isEasterSeasonLabel(label)) ||
        (!isEasterSeason(seasons) && isNonEasterSeasonLabel(label))

      if (!shouldShow) {
        return ''
      }

      const cleanText = text.trim()
      return cleanText ? ` ${cleanText}` : ''
    },
  )
}

function selectSeasonalAntiphon(value: string, seasons?: string[]): string {
  if (!hasText(value) || !seasons?.length) {
    return value
  }

  const normalizedValue = selectInlineSeasonalText(value, seasons)
  const marker =
    /^\s*\$?\s*((?:fuera\s+del\s+tiempo\s+pascual|fuera\s+de\s+pascua|no\s+pascua|si\s+no\s+es\s+pascua|en\s+tiempo\s+pascual|tiempo\s+pascual|pascua|si\s+es\s+pascua))\s*:\s*\$?\s*(.*)$/i
  const hasSeasonalLabels =
    /(^|\n)\s*\$?\s*(?:fuera\s+del\s+tiempo\s+pascual|fuera\s+de\s+pascua|no\s+pascua|si\s+no\s+es\s+pascua|en\s+tiempo\s+pascual|tiempo\s+pascual|pascua|si\s+es\s+pascua)\s*:/i.test(
      normalizedValue,
    )

  if (!hasSeasonalLabels) {
    return normalizedValue
  }

  const lines = normalizedValue.split(/\r?\n/)
  const bySeason = new Map<'easter' | 'nonEaster', string[]>()
  bySeason.set('easter', [])
  bySeason.set('nonEaster', [])

  let active: 'easter' | 'nonEaster' | null = null
  for (const rawLine of lines) {
    const markerMatch = rawLine.match(marker)
    if (markerMatch) {
      const label = markerMatch[1] ?? ''

      if (isEasterSeasonLabel(label)) {
        active = 'easter'
      } else if (isNonEasterSeasonLabel(label)) {
        active = 'nonEaster'
      } else {
        active = null
      }

      const markerText = (markerMatch[2] ?? '').trim()
      if (active && markerText.length) {
        bySeason.get(active)?.push(markerText)
      }
      continue
    }

    if (active) {
      bySeason.get(active)?.push(rawLine)
    }
  }

  const selected = bySeason.get(isEasterSeason(seasons) ? 'easter' : 'nonEaster')
  const selectedText = selected?.join('\n').trim()
  if (!selectedText) {
    const fallback = bySeason.get(isEasterSeason(seasons) ? 'nonEaster' : 'easter')
    const fallbackText = fallback?.join('\n').trim()
    if (fallbackText) {
      return fallbackText
    }
    return value
  }

  return selectedText
}

function selectAntiphonText(value: string, cycle?: string, seasons?: string[]): string {
  return selectCycleText(selectSeasonalAntiphon(value, seasons), cycle)
}

function isLent(seasons?: string[]): boolean {
  return Boolean(seasons?.some((season) => season.includes('LENT')))
}

function isAdventOrChristmas(seasons?: string[]): boolean {
  return hasSeason(seasons, 'ADVENT') || hasSeason(seasons, 'CHRISTMAS')
}

function isBeforeOrOnPresentation(date: Date): boolean {
  return date.getMonth() === 0 || (date.getMonth() === 1 && date.getDate() <= 2)
}

function marianAntiphonKind(settings: PrayerBuildSettings): MarianAntiphonKind {
  if (isEasterSeason(settings.seasons)) {
    return 'reginaCaeli'
  }

  if (
    isAdventOrChristmas(settings.seasons) ||
    (settings.date ? isBeforeOrOnPresentation(settings.date) : false)
  ) {
    return 'almaRedemptoris'
  }

  if (settings.date && settings.date < easterDate(settings.date.getFullYear())) {
    return 'aveRegina'
  }

  if (isLent(settings.seasons)) {
    return 'aveRegina'
  }

  return 'salveRegina'
}

const MARIAN_ANTIPHON_LABELS: Record<MarianAntiphonKind, string> = {
  almaRedemptoris: 'Santa Madre del Redentor',
  aveRegina: 'Salve, Reina de los cielos',
  reginaCaeli: 'Reina del cielo',
  salveRegina: 'Salve Regina',
}

function marianAntiphonSection(settings: PrayerBuildSettings): PrayerSection {
  const defaultKind = marianAntiphonKind(settings)
  const orderedKinds = [
    defaultKind,
    ...(['almaRedemptoris', 'aveRegina', 'reginaCaeli', 'salveRegina'] as MarianAntiphonKind[]).filter(
      (kind) => kind !== defaultKind,
    ),
  ]

  return {
    title: 'Antífona mariana',
    alternatives: orderedKinds.map((kind) => ({
      label: MARIAN_ANTIPHON_LABELS[kind],
      content: marianAntiphon(kind),
    })),
  }
}

function antiphon(value: string): string {
  return hasText(value) ? `[[ANTIPHON]] ${value}` : ''
}

function repeatedAntiphon(value: string): string {
  return hasText(value) ? `[[REPEATED_ANTIPHON]] ${value}` : ''
}

function optionalAlternativeParts(value: string | undefined): string[] {
  const text = value?.replace(/\r\n/g, '\n').trim()

  if (!text) {
    return []
  }

  return text
    .split(/(?:^|\n)\s*\$?\s*O\s+bien\s*:?\s*\$?\s*/gim)
    .map((part) => part.trim())
    .filter(Boolean)
}

function hymnSection(content: string): PrayerSection {
  return sectionWithOptionalAlternatives('Himno', content, 'Himno')
}

