function sectionWithOptionalAlternatives(
  title: string,
  content: string,
  labelPrefix = 'Opción',
  wrap?: (text: string) => string,
): PrayerSection {
  const alternatives = optionalAlternativeParts(content)
  const applyWrap = (text: string) => (wrap ? wrap(text) : text)

  if (alternatives.length <= 1) {
    return { title, content: applyWrap(content) }
  }

  return {
    title,
    alternatives: alternatives.map((part, index) => ({
      label: `${labelPrefix} ${index + 1}`,
      content: applyWrap(part),
    })),
  }
}

/** La oración final se decía sin que quedara marcada la respuesta del pueblo -- faltaba el
 * "Amén" (pedido de Lucas, 30/08/2026): mismo patrón que ya usa `conclusion('blessing')` en
 * fixed-prayers.ts ("$V.$ ...\n$R.$ Amén."), todo el cuerpo de la oración bajo V., el Amén en
 * su propio bloque. */
function withFinalPrayerResponse(text: string): string {
  return hasText(text) ? `$V.$ ${text}\n\n$R.$ Amén.` : text
}

function canticleWithAntiphonSection(
  title: string,
  canticle: string,
  dailyAntiphon: string,
  repeatFinalAntiphon = true,
): PrayerSection {
  const alternatives = optionalAlternativeParts(dailyAntiphon)

  function contentFor(antiphonText: string): string {
    const finalAntiphon = repeatFinalAntiphon ? repeatedAntiphon(antiphonText) : antiphon(antiphonText)

    return [antiphon(antiphonText), RUBRIC_SIGN_OF_CROSS, canticle, GLORIA, finalAntiphon]
      .filter(hasText)
      .join('\n\n')
  }

  if (alternatives.length <= 1) {
    return {
      title,
      content: contentFor(dailyAntiphon),
    }
  }

  return {
    title,
    alternatives: alternatives.map((antiphonText, index) => ({
      label: `Antífona ${index + 1}`,
      content: contentFor(antiphonText),
    })),
  }
}

function invitatoryPsalmContent(psalmText: string, antiphonText: string): string {
  const repeated = repeatedAntiphon(antiphonText)
  const content = hasText(repeated)
    ? psalmText.replace(/<small\b[^>]*>\s*Se repite la ant.fona\s*<\/small>/gi, `\n${repeated}\n`)
    : psalmText

  return cleanPsalmHtml(content)
}

function cleanPsalmHtml(value: string): string {
  return value
    .replace(/<\/p>\s*<p\b[^>]*>/gi, '\n\n')
    .replace(/<p\b[^>]*>/gi, '')
    .replace(/<\/p>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/?[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim()
}

function stripInvitatoryGloria(value: string): string {
  return value
    .replace(
      /(?:^|\n+)\s*Gloria al Padre,\s*y al Hijo,\s*y al Esp[íi]ritu Santo\.?\s+(?:Como era en el principio,\s*)?ahora y siempre,?\s+por los siglos de los siglos\.?\s*Am[eé]n\.?/gi,
      '\n',
    )
    .replace(
      /(?:^|\n+)\s*Gloria al Padre,\s*y al Hijo,\s*y al Esp[íi]ritu Santo\.?\s+Como era en el principio,\s*ahora y siempre,?\s+por los siglos de los siglos\.?\s*Am[eé]n\.?/gi,
      '\n',
    )
    .replace(/\n{3,}/g, '\n\n')
    .trim()
}

function regularPsalmFromInvitatory(psalmText: string): string {
  return cleanPsalmHtml(psalmText.replace(/<small\b[^>]*>\s*Se repite la ant.fona\s*<\/small>/gi, ''))
}

function cleanInvitatoryReplacementRubric(value: string): string {
  return value
    .replace(/\n+\s*_?Si se ha rezado este salmo en el invitatorio, se reemplaza por el Salmo 94, que se encuentra m(?:Ã¡|á)s arriba\._?/gi, '')
    .trim()
}

function hasInvitatoryReplacementRubric(value: string): boolean {
  return /Si se ha rezado este salmo en el invitatorio, se reemplaza por el Salmo 94/i.test(value)
}

function psalmContent(antiphonText: string, psalmText: string): string {
  if (!hasText(antiphonText) && !hasText(psalmText)) {
    return ''
  }

  return [antiphon(antiphonText), psalmText, repeatedAntiphon(antiphonText)]
    .filter(hasText)
    .join('\n\n')
}

function pushSection(sections: PrayerSection[], section: PrayerSection): void {
  if (hasText(section.content) || section.alternatives?.length || section.items?.length) {
    sections.push(section)
  }
}

function pushPsalm(
  sections: PrayerSection[],
  record: PrayerRecord,
  title: string,
  prefix: 'primer' | 'segundo' | 'tercer',
  cycle?: string,
  seasons?: string[],
  invitatoryContext?: InvitatoryPsalmContext,
): void {
  const rawEyebrow = asText(record, `${prefix}_salmo_cita`)
  const rawPsalmText = asText(record, `${prefix}_salmo_texto`)
  const shouldReplace =
    Boolean(invitatoryContext?.canReplace) &&
    hasInvitatoryReplacementRubric(rawEyebrow) &&
    psalmNumber(rawEyebrow) === invitatoryContext?.selectedPsalmNumber &&
    Boolean(invitatoryContext?.replacementPsalm)
  const replacementPsalm = invitatoryContext?.replacementPsalm
  const eyebrow = shouldReplace && replacementPsalm ? replacementPsalm.title : cleanInvitatoryReplacementRubric(rawEyebrow)
  const psalmText = shouldReplace && replacementPsalm ? regularPsalmFromInvitatory(replacementPsalm.psalm) : rawPsalmText

  pushSection(sections, {
    title,
    eyebrow,
    content: psalmContent(
      selectAntiphonText(asText(record, `${prefix}_salmo_antifona`), cycle, seasons),
      psalmText,
    ),
  })
}

function selectedInvitatoryPsalm(record: PrayerRecord, settings: PrayerBuildSettings): InvitatoryPsalm | undefined {
  const psalms = asInvitatoryPsalms(record)
  const index = Math.max(0, Math.min(psalms.length - 1, settings.invitatoryPsalmIndex ?? 0))

  return psalms[index]
}

function invitatoryPsalmContext(record: PrayerRecord, settings: PrayerBuildSettings, hour: HourKey): InvitatoryPsalmContext {
  const psalms = asInvitatoryPsalms(record)
  const selectedPsalm = selectedInvitatoryPsalm(record, settings)
  const replacementPsalm = psalms.find((psalm) => psalmNumber(psalm.title) === 94)

  return {
    canReplace: hour === 'laudes' && settings.includeInvitatoryInLaudes && Boolean(selectedPsalm && replacementPsalm),
    selectedPsalmNumber: selectedPsalm ? psalmNumber(selectedPsalm.title) : undefined,
    replacementPsalm,
  }
}

function invitatorySections(record: PrayerRecord, settings: PrayerBuildSettings): PrayerSection[] {
  const invitatoryAntiphon = asText(record, '__invitatoryAntiphon') || asText(record, 'val')
  const invitatoryPsalms = asInvitatoryPsalms(record)
  const fallbackPsalm = {
    title: asText(record, '__invitatoryPsalmTitle') || asText(record, 'psalmTitle'),
    psalm: asText(record, '__invitatoryPsalm') || asText(record, 'psalm'),
  }
  const psalms = invitatoryPsalms.length ? invitatoryPsalms : fallbackPsalm.title && fallbackPsalm.psalm ? [fallbackPsalm] : []
  const selectedIndex = Math.max(0, Math.min(psalms.length - 1, settings.invitatoryPsalmIndex ?? 0))
  const selectedPsalm = psalms[selectedIndex]
  const alternatives = psalms.map((psalm, index) => ({
    label: invitatoryTabLabel(psalm.title, index),
    eyebrow: psalm.title,
    content: [
      stripInvitatoryGloria(invitatoryPsalmContent(psalm.psalm, invitatoryAntiphon)),
      GLORIA,
      repeatedAntiphon(invitatoryAntiphon),
    ]
      .filter(hasText)
      .join('\n\n'),
  }))

  return [
    {
      title: 'Aclamación',
      content: INVITATORY_OPENING,
    },
    {
      title: 'Antífona',
      content: antiphon(invitatoryAntiphon),
      quiet: true,
    },
    {
      title: 'Salmo invitatorio',
      eyebrow: selectedPsalm?.title,
      alternatives,
    },
  ]
}

function openingSections(record: PrayerRecord, settings: PrayerBuildSettings, hour: HourKey): PrayerSection[] {
  if (hour === 'laudes' && settings.includeInvitatoryInLaudes) {
    return invitatorySections(record, settings)
  }

  return [
    {
      title: 'Invocación inicial',
      content: openingPrayer(isLent(settings.seasons)),
    },
  ]
}

function evangelicalCanticle(hour: HourKey, dailyAntiphon: string): PrayerSection {
  const canticle = hour === 'vesperae' ? MAGNIFICAT : BENEDICTUS
  const title = hour === 'vesperae' ? 'Cántico de María' : 'Cántico de Zacarías'

  return canticleWithAntiphonSection(title, canticle, dailyAntiphon)
}

function customIntentionsItem(customIntentions: string, response: string): string {
  const intentions = customIntentions
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(hasText)
    .flatMap((line) => {
      const bold = line.startsWith('*')
      const text = bold ? line.slice(1).trimStart() : line
      const rendered = bold ? `<strong>${escapeHtml(text)}</strong>` : escapeHtml(text)
      const petitionClass = bold ? 'personal-intention-line is-bold' : 'personal-intention-line'
      const petitionLine = `<span class="${petitionClass}">- ${rendered}</span>`
      const responseLine = bold && hasText(response)
        ? `<span class="custom-preces-response-line">$R.$ ${escapeHtml(response)}</span>`
        : ''

      return [petitionLine, responseLine].filter(hasText)
    })

  if (!intentions.length) {
    return ''
  }

  return `<p class="personal-intentions-block">${intentions.join('')}</p>`
}

const VESPERAE_PERSONAL_INTENTIONS_PROMPT = 'pueden añadirse intenciones personales'

function balanceItalicMarkers(value: string): string {
  const markerCount = (value.match(/_/g) ?? []).length

  return markerCount % 2 === 1 ? `${value}_` : value
}

function cleanPrecesItem(item: string): string {
  return balanceItalicMarkers(
    item
      .trim()
      .replace(/^\s*-\s*\(\s*o\s+bien\s*:?\s*/i, '- ')
      .replace(/\s*\(\s*o\s+bien\s*:?\s*_?\s*$/i, '')
      .replace(/\)\s*(_?)\s*$/i, '$1')
      .trim(),
  )
}

function precesSection(record: PrayerRecord, customIntentions: string, hour: HourKey): PrayerSection {
  const response = asText(record, 'preces_respuesta')
  const dailyIntentions = asItems(record, 'preces_contenido').map(cleanPrecesItem)
  const responseLine = hasText(response) ? `$R.$ ${response}` : ''
  const hasCustomIntentions = hasText(customIntentions)
  const items: string[] = []

  if (hasText(responseLine)) {
    items.push(responseLine)
  }

  dailyIntentions.forEach((item) => {
    items.push([item, responseLine].filter(hasText).join('\n\n'))
  })

  if (hasCustomIntentions) {
    items.push(customIntentionsItem(customIntentions, response))
  } else if (hour === 'vesperae') {
    items.push(VESPERAE_PERSONAL_INTENTIONS_PROMPT)
  }

  if (hasCustomIntentions && hasText(responseLine)) {
    items.push(responseLine)
  }

  return {
    title: 'Preces',
    content: asText(record, 'preces_intro'),
    items,
  }
}

function lordPrayerSection(record: PrayerRecord, settings: PrayerBuildSettings): PrayerSection {
  return {
    title: 'Padrenuestro',
    content: [asText(record, 'invitacion_padrenuestro'), lordPrayer(settings.lordPrayerLanguage)]
      .filter(hasText)
      .join('\n\n'),
    quiet: true,
  }
}

function conclusionKind(hour: HourKey): ConclusionKind | undefined {
  if (hour === 'laudes' || hour === 'vesperae') {
    return 'blessing'
  }

  if (hour === 'completorium') {
    return 'compline'
  }

  if (hour === 'invitatorium' || hour === 'officium' || hour === 'tertia' || hour === 'sexta' || hour === 'nona') {
    return 'short'
  }

  return undefined
}

function pushConclusion(sections: PrayerSection[], hour: HourKey): void {
  const kind = conclusionKind(hour)

  if (kind) {
    pushSection(sections, {
      title: 'Conclusión',
      content: conclusion(kind),
      quiet: true,
    })
  }
}

function commonHourSections(record: PrayerRecord, settings: PrayerBuildSettings, hour: HourKey): PrayerSection[] {
  const sections: PrayerSection[] = []
  const invitatoryContext = invitatoryPsalmContext(record, settings, hour)

  for (const section of openingSections(record, settings, hour)) {
    pushSection(sections, section)
  }
      pushSection(sections, hymnSection(asText(record, 'himno')))
  pushPsalm(sections, record, 'Primer salmo', 'primer', settings.cycle, settings.seasons, invitatoryContext)
  pushPsalm(sections, record, 'Segundo salmo', 'segundo', settings.cycle, settings.seasons, invitatoryContext)
  pushPsalm(sections, record, 'Tercer salmo', 'tercer', settings.cycle, settings.seasons, invitatoryContext)
  pushSection(sections, {
    title: 'Lectura breve',
    eyebrow: readingEyebrow(asText(record, 'lectura_biblica_cita')),
    content: cleanReadingText(asText(record, 'lectura_biblica')),
  })
  pushSection(sections, { title: 'Responsorio breve', items: withResponsorySplitMark(asItems(record, 'responsorios')) })

  if (hour === 'laudes' || hour === 'vesperae') {
      pushSection(
        sections,
        evangelicalCanticle(
          hour,
          selectAntiphonText(asText(record, 'cantico_evangelico_antifona'), settings.cycle, settings.seasons),
        ),
      )
    pushSection(sections, precesSection(record, settings.customIntentions, hour))
    pushSection(sections, lordPrayerSection(record, settings))
  }

  pushSection(
    sections,
    sectionWithOptionalAlternatives('Oración final', asText(record, 'oracion_final'), 'Oración', withFinalPrayerResponse),
  )
  pushConclusion(sections, hour)
  if (hour === 'laudes' && settings.includeMarianConsecrationInLaudes) {
    pushSection(sections, { title: 'Consagración a María', content: MARIAN_CONSECRATION })
  }
  return sections
}

function completoriumResponsory(record: PrayerRecord, settings: PrayerBuildSettings): string[] {
  const easterResponsory = asItems(record, 'responsorio_pascua')

  if (isEasterSeason(settings.seasons) && easterResponsory.length) {
    return easterResponsory
  }

  return withResponsorySplitMark(asItems(record, 'responsorio'))
}

function completoriumCanticleAntiphon(record: PrayerRecord, settings: PrayerBuildSettings): string {
  if (isPaschalTriduum(settings.seasons)) {
    const triduumAntiphon = asText(record, 'antifona_triduo')
    if (hasText(triduumAntiphon)) {
      return triduumAntiphon
    }
  }

  if (isEasterOctave(settings.seasons)) {
    const easterOctaveAntiphon = asText(record, 'antifona_inalbis')
    if (hasText(easterOctaveAntiphon)) {
      return easterOctaveAntiphon
    }
  }

  return selectAntiphonText(asText(record, 'cantico_evangelico_antifona'), settings.cycle, settings.seasons)
}

function cleanComplinePrayerText(value: string): string {
  const body = value
    .replace(/\r\n/g, '\n')
    .replace(/^\s*(?:<p[^>]*>\s*)?Completas\s*:[\s\S]*?(?=(?:<p[^>]*>\s*)?(?:\$V\.\$\s*)?Oremos\s*:?\s*)/i, '')
    .replace(/^\s*(?:<p[^>]*>\s*)?Completas\s*:[^\n<]*(?:<\/p>)?\s*/i, '')
    .replace(/^\s*(?:<p[^>]*>\s*)?(?:\$V\.\$\s*)?Oremos\s*:?\s*(?:<\/p>)?\s*/i, '')
    .replace(/\s*(?:\$R\.\$\s*)?Am[eé]n\.?\s*$/i, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim()

  return ['$V.$ Oremos.', body, '$R.$ Amén.'].filter(hasText).join('\n\n')
}

function completoriumSections(record: PrayerRecord, settings: PrayerBuildSettings): PrayerSection[] {
  const sections: PrayerSection[] = []

  for (const section of openingSections(record, settings, 'completorium')) {
    pushSection(sections, section)
  }
  pushSection(sections, complineExaminationSection())
  pushSection(sections, hymnSection(asText(record, 'himno')))
  pushPsalm(sections, record, 'Primer salmo', 'primer')
  pushPsalm(sections, record, 'Segundo salmo', 'segundo')
  pushSection(sections, {
    title: 'Lectura breve',
    eyebrow: readingEyebrow(asText(record, 'lectura_biblica_cita')),
    content: cleanReadingText(asText(record, 'lectura_biblica_texto')),
  })
  pushSection(sections, { title: 'Responsorio', items: withResponsorySplitMark(completoriumResponsory(record, settings)) })
  const canticleAntiphon = completoriumCanticleAntiphon(record, settings)
  pushSection(sections, canticleWithAntiphonSection('Cántico evangélico', NUNC_DIMITTIS, canticleAntiphon, true))
  pushSection(
    sections,
    sectionWithOptionalAlternatives(
      'Oración',
      cleanComplinePrayerText([asText(record, 'oracion'), asText(record, 'final')].filter(hasText).join('\n\n')),
      'Oración',
    ),
  )
  pushConclusion(sections, 'completorium')
  pushSection(sections, marianAntiphonSection(settings))

  return sections
}

function officiumSections(record: PrayerRecord, settings: PrayerBuildSettings): PrayerSection[] {
  const sections: PrayerSection[] = []
  const track = settings.officeTrack
  const trackLabel = track === 'a' ? 'anual' : track === 'i' ? 'año impar' : 'año par'

  for (const section of openingSections(record, settings, 'officium')) {
    pushSection(sections, section)
  }
  pushSection(sections, hymnSection(asText(record, 'himno')))
  pushPsalm(sections, record, 'Primer salmo', 'primer')
  pushPsalm(sections, record, 'Segundo salmo', 'segundo')
  pushPsalm(sections, record, 'Tercer salmo', 'tercer')
  pushSection(sections, { title: 'Responsorio', items: withResponsorySplitMark(asItems(record, 'responsorio1')) })
  pushSection(sections, {
    title: `Lectura bíblica (${trackLabel})`,
    eyebrow: readingEyebrow(asText(record, `lectura_biblica_cita_${track}`)),
    summary: asText(record, `lectura_biblica_titulo_${track}`),
    content: cleanReadingText(asText(record, `lectura_biblica_texto_${track}`)),
  })
  pushSection(sections, {
    title: 'Responsorio',
    items: withResponsorySplitMark(officeReadingResponsory(asItems(record, `responsorio2_${track}`))),
  })
  pushSection(sections, {
    title: `Lectura patrística (${trackLabel})`,
    eyebrow: stripInlineMarkers(asText(record, `lectura_patristica_cita_${track}`)),
    summary: asText(record, `lectura_patristica_titulo_${track}`),
    content: asText(record, `lectura_patristica_texto_${track}`),
  })
  pushSection(sections, {
    title: 'Responsorio',
    items: withResponsorySplitMark(officeReadingResponsory(asItems(record, `responsorio3_${track}`))),
  })
  pushSection(sections, sectionWithOptionalAlternatives('Oración final', asText(record, 'oracion_final'), 'Oración'))
  pushConclusion(sections, 'officium')

  return sections
}

function massReadingTitle(type: string, readings: PrayerRecord[]): string {
  if (
    isSecondReadingType(type) &&
    !readings.some((reading) => isFirstReadingType(massReadingType(reading)))
  ) {
    return 'Primera lectura'
  }

  return massReadingTitles[type] ?? 'Lectura'
}

function massReadingSections(record: PrayerRecord, settings: PrayerBuildSettings): PrayerSection[] {
  const readings = massReadings(record, settings.seasons)

  return readings.map((reading) => {
    const type = massReadingType(reading)
    const text = asText(reading, 'texto')
    const ref = normalizeMassScriptureRef(asText(reading, 'ref'), text)
    const isScriptureReading = !isMassPsalmType(type) && !isMassGospelType(type) && !isMassAcclamationType(type)
    const eyebrow = isScriptureReading ? '' : ref

    return {
      title: massReadingTitle(type, readings),
      eyebrow: hasText(eyebrow) ? eyebrow : undefined,
      content: isMassPsalmType(type)
        ? massPsalmContent(ref, text)
        : isMassGospelType(type)
          ? massGospelContent(ref, text)
          : isMassAcclamationType(type)
            ? massAcclamationContent(ref, text, settings)
            : massScriptureReadingContent(ref, text),
      kind: 'mass',
      quiet: isMassAcclamationType(type),
    }
  })
}

function massGospelBuildSettings(record: PrayerRecord, settings: PrayerBuildSettings): PrayerBuildSettings {
  const gospel = massReadings(record, settings.seasons).find((reading) => isMassGospelType(massReadingType(reading)))

  if (!gospel) {
    return settings
  }

  const text = asText(gospel, 'texto')
  const ref = normalizeMassScriptureRef(asText(gospel, 'ref'), text)

  return {
    ...settings,
    massGospelReference: ref,
    massGospelText: text,
  }
}

function settingHasSeason(settings: PrayerBuildSettings, season: string): boolean {
  return (settings.seasons ?? []).some((value) => value.toLowerCase().includes(season))
}

function shouldIncludeGloriaInMass(settings: PrayerBuildSettings): boolean {
  const rank = settings.rank?.toUpperCase()

  if (isHolyThursdayCelebration(settings)) {
    return true
  }

  if (rank === 'SOLEMNITY' || rank === 'FEAST') {
    return true
  }

  return rank === 'SUNDAY' && !settingHasSeason(settings, 'advent') && !settingHasSeason(settings, 'lent')
}

function shouldIncludeCreedInMass(settings: PrayerBuildSettings): boolean {
  const rank = settings.rank?.toUpperCase()

  if (isHolyThursdayCelebration(settings)) {
    return false
  }

  return rank === 'SUNDAY' || rank === 'SOLEMNITY'
}

function sectionHasRenderableContent(section: PrayerSection): boolean {
  return Boolean(
    section.kind === 'part' ||
      hasText(section.content) ||
      hasText(section.summary) ||
      section.rubrics?.some(hasText) ||
      section.alternatives?.some((alternative) => hasText(alternative.content)) ||
      section.items?.length,
  )
}

type PrayerPosture = 'stand' | 'sit' | 'kneel'

const RUBRIC_STAND = '$Nos ponemos en pie$'
const RUBRIC_SIT = '$Nos sentamos$'
const RUBRIC_KNEEL_CONSECRATION = '$Nos arrodillamos durante la consagración.$'
const RUBRIC_SIGN_OF_CROSS = '$† Hacemos la señal de la cruz mientras decimos: †$'
const RUBRIC_SIGN_OF_CROSS_ON_LIPS = '$† Hacemos la señal de la cruz mientras decimos: †$'
const RUBRIC_GOSPEL_SIGN_OF_CROSS = '$† Hacemos la señal de la cruz mientras decimos: †$'
const RUBRIC_BLESSING_SIGN_OF_CROSS = '$† Hacemos la señal de la cruz mientras decimos: †$'

function normalizedSectionTitle(title: string): string {
  return title
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
}

function withRubrics(section: PrayerSection, rubrics: string[]): PrayerSection {
  const cleanRubrics = rubrics.filter(hasText)

  if (!cleanRubrics.length || section.kind === 'part') {
    return section
  }

  const mergedRubrics = [...(section.rubrics ?? [])]

  for (const rubric of cleanRubrics) {
    if (!mergedRubrics.includes(rubric)) {
      mergedRubrics.push(rubric)
    }
  }

  return { ...section, rubrics: mergedRubrics }
}

function postureForRubric(rubric: string): PrayerPosture | undefined {
  if (rubric === RUBRIC_STAND) {
    return 'stand'
  }

  if (rubric === RUBRIC_SIT) {
    return 'sit'
  }

  if (rubric === RUBRIC_KNEEL_CONSECRATION) {
    return 'kneel'
  }

  return undefined
}

function keepPostureChangesOnly(sections: PrayerSection[]): PrayerSection[] {
  let currentPosture: PrayerPosture | undefined

  return sections.map((section) => {
    const rubrics = section.rubrics ?? []
    if (!rubrics.length) {
      return section
    }

    const filteredRubrics: string[] = []

    rubrics.forEach((rubric) => {
      const posture = postureForRubric(rubric)

      if (!posture) {
        filteredRubrics.push(rubric)
        return
      }

      if (posture !== currentPosture) {
        filteredRubrics.push(rubric)
        currentPosture = posture
      }
    })

    return filteredRubrics.length ? { ...section, rubrics: filteredRubrics } : { ...section, rubrics: undefined }
  })
}

function hourSectionRubrics(hour: HourKey, section: PrayerSection): string[] {
  const title = normalizedSectionTitle(section.title)

  if (title === 'aclamacion') {
    return [RUBRIC_STAND, RUBRIC_SIGN_OF_CROSS_ON_LIPS]
  }

  if (hour === 'invitatorium' && (title === 'antifona' || title === 'salmo invitatorio')) {
    return [RUBRIC_STAND]
  }

  if (title === 'invocacion inicial') {
    return [RUBRIC_STAND, RUBRIC_SIGN_OF_CROSS]
  }

  if (title === 'himno') {
    return [RUBRIC_STAND]
  }

  if (title === 'examen de conciencia') {
    return [RUBRIC_SIT]
  }

  if (title === 'primer salmo' || title === 'segundo salmo' || title === 'tercer salmo') {
    return [RUBRIC_SIT]
  }

  if (title.startsWith('lectura') || title === 'responsorio' || title === 'responsorio breve') {
    return [RUBRIC_SIT]
  }

  if (title === 'cantico de zacarias' || title === 'cantico de maria' || title === 'cantico evangelico') {
    return [RUBRIC_STAND]
  }

  if (
    title === 'preces' ||
    title === 'padre nuestro' ||
    title === 'antifona mariana' ||
    title === 'consagracion a maria' ||
    title.includes('oracion')
  ) {
    return [RUBRIC_STAND]
  }

  if (title === 'conclusion') {
    return hour === 'laudes' || hour === 'vesperae' || hour === 'completorium'
      ? [RUBRIC_STAND, RUBRIC_SIGN_OF_CROSS]
      : [RUBRIC_STAND]
  }

  return []
}

function massSectionRubrics(section: PrayerSection): string[] {
  const title = normalizedSectionTitle(section.title)

  if (title === 'senal de la cruz') {
    return [RUBRIC_STAND, RUBRIC_SIGN_OF_CROSS]
  }

  if (title === 'evangelio') {
    return [RUBRIC_STAND, RUBRIC_GOSPEL_SIGN_OF_CROSS]
  }

  if (title === 'bendicion') {
    return [RUBRIC_STAND, RUBRIC_BLESSING_SIGN_OF_CROSS]
  }

  if (
    title === 'primera lectura' ||
    title === 'segunda lectura' ||
    title === 'salmo responsorial' ||
    title === 'salmo responsorial cantado' ||
    title === 'secuencia' ||
    title === 'homilia' ||
    title === 'avisos' ||
    title === 'canto de ofertorio' ||
    title === 'presentacion de los dones' ||
    title === 'canto de meditacion'
  ) {
    return [RUBRIC_SIT]
  }

  if (title === 'plegaria eucaristica') {
    return [RUBRIC_STAND, RUBRIC_KNEEL_CONSECRATION]
  }

  if (
    title.includes('evangelio') ||
    title.includes('aclamacion') ||
    title.includes('gloria') ||
    title.includes('credo') ||
    title.includes('profesion de fe') ||
    title.includes('oracion') ||
    title.includes('prefacio') ||
    title.includes('santo') ||
    title.includes('padrenuestro') ||
    title.includes('cordero de dios') ||
    title.includes('comunion') ||
    title.includes('bendicion') ||
    title.includes('despedida') ||
    title.includes('veneracion del altar') ||
    title === 'antifona de entrada' ||
    title === 'canto de entrada' ||
    title === 'saludo inicial' ||
    title === 'monicion inicial' ||
    title === 'acto penitencial y senor, ten piedad' ||
    title === 'senor, ten piedad' ||
    title === 'orad, hermanos' ||
    title === 'dialogo del prefacio' ||
    title === 'monicion a la plegaria eucaristica' ||
    title === 'continuacion de la plegaria eucaristica' ||
    title === 'doxologia final y gran amen' ||
    title === 'rito de la paz' ||
    title === 'invitacion a la comunion' ||
    title === 'canto final'
  ) {
    return [RUBRIC_STAND]
  }

  return []
}

function annotateSectionsForHour(hour: HourKey, sections: PrayerSection[]): PrayerSection[] {
  return keepPostureChangesOnly(
    sections.map((section) =>
      withRubrics(section, hour === 'evangelium' ? massSectionRubrics(section) : hourSectionRubrics(hour, section)),
    ),
  )
}

function goodFridayPassionSections(record: PrayerRecord, settings: PrayerBuildSettings): PrayerSection[] {
  const massSettings = massGospelBuildSettings(record, settings)
  const readings = massReadingSections(record, massSettings)
  const songSection = (section: MassSongSectionKey) => choirSongSection(section, record, massSettings)
  const sections: PrayerSection[] = [...goodFridayOpeningSections()]

  readings.forEach((section) => {
    if (section.title === 'Salmo responsorial') {
      sections.push(songSection('salmo'))
    }

    if (section.title === 'Aclamación antes del Evangelio') {
      sections.push(songSection('aclamacion'))
    }

    sections.push(section)

    if (section.title === 'Evangelio') {
      sections.push(massPostGospelAcclamationSection())
    }
  })

  sections.push(
    {
      title: 'Homilía',
      content: '$Rúbrica.$ Homilía.\n\n$Rúbrica.$ Puede guardarse un momento de silencio.',
      kind: 'mass',
      quiet: true,
    },
    goodFridaySolemnIntercessionsSection(),
    ...goodFridayVenerationSections(),
    ...goodFridayCommunionSections(settings, songSection),
  )

  return massViewForSettings(sections, settings)
}

function easterVigilMassSections(record: PrayerRecord, settings: PrayerBuildSettings): PrayerSection[] {
  const massSettings = massGospelBuildSettings(record, settings)
  const readings = massReadingSections(record, massSettings)
  const songSection = (section: MassSongSectionKey) => choirSongSection(section, record, massSettings)
  const sections: PrayerSection[] = [...easterVigilOpeningSections(), massPart('Liturgia de la Palabra')]
  const collectSection = massIntroductorySections(settings, songSection, false).find(
    (section) => section.title === 'Oración colecta',
  )
  let hasInsertedGloriaAndCollect = false

  function pushGloriaAndCollect(): void {
    if (hasInsertedGloriaAndCollect) {
      return
    }

    sections.push(songSection('gloria'))
    sections.push({
      title: 'Gloria',
      content: GLORIA,
      kind: 'mass',
      quiet: true,
    })

    if (collectSection) {
      sections.push(collectSection)
    }

    hasInsertedGloriaAndCollect = true
  }

  readings.forEach((section) => {
    if (section.title === 'Epístola') {
      pushGloriaAndCollect()
    }

    if (section.title.startsWith('Salmo responsorial')) {
      sections.push(songSection('salmo'))
    }

    if (section.title === 'Aclamación antes del Evangelio') {
      sections.push(songSection('aclamacion'))
    }

    sections.push(section)

    if (section.title === 'Evangelio') {
      sections.push(massPostGospelAcclamationSection())
    }

    if (section.title.startsWith('Salmo responsorial')) {
      const readingPrayer = easterVigilPrayerAfterPsalmSection(section.title)

      if (readingPrayer) {
        sections.push(readingPrayer)
      }
    }
  })

  pushGloriaAndCollect()

  const afterReadings = massWordAfterReadingsSections(settings, false)
  const homily = afterReadings.find((section) => section.title === 'Homilía')
  const universalPrayer = afterReadings.find((section) => section.title === 'Oración universal')

  if (homily) {
    sections.push(homily)
  }

  sections.push(...easterVigilBaptismalSections())

  if (universalPrayer) {
    sections.push(universalPrayer)
  }

  sections.push(
    massPart('Liturgia eucarística'),
    ...massEucharisticSections(settings, songSection),
    massPart('Rito de la comunión'),
    ...massCommunionSections(settings, songSection),
    massPart('Ritos conclusivos'),
    ...massConcludingSections(settings, songSection),
  )

  return massViewForSettings(sections, settings)
}

/**
 * Vista por defecto de la Misa: solo lo que se canta desde el coro, todo seguido y sin los
 * separadores de partes ("Ritos iniciales", "Liturgia de la Palabra"...). Con el Modo Sacerdote
 * encendido (ajuste, apagado por defecto) se ve la Misa entera, como hasta el 06/09/2026.
 *
 * Pedido de Lucas ese día: "todo lo que ahora está puesto en misa ponlo en modo Sacerdote, por
 * defecto desactivado (...) y sin eso activado déjalo solo para lo que tenemos que cantar desde
 * el coro: canción de entrada, de aspersión opcional, Piedad, Gloria, Antífona del salmo,
 * aleluya, Ofertorio, Cordero, comunión y salida, todo seguidito con opciones".
 *
 * Dos decisiones que conviene no volver a discutir cada vez:
 * - **La aspersión no es sección propia**: ya existe como alternativa ("Aspersión I", "Aspersión
 *   II", "Aspersión pascual") dentro del acto penitencial, y por eso esa sección se conserva
 *   entera en la vista de coro -- es donde se elige.
 * - **Antífona del salmo y aleluya son el texto del día**, no una sugerencia de canto: se
 *   conservan "Salmo responsorial" y "Aclamación antes del Evangelio" además de sus secciones
 *   de canto, porque es el texto concreto lo que el coro canta.
 */
const CHOIR_MASS_TITLES = new Set<string>([
  massSongTitle('entrada'),
  massSongTitle('penitencial'),
  'Acto penitencial y Señor, ten piedad',
  massSongTitle('gloria'),
  'Gloria',
  massSongTitle('salmo'),
  'Salmo responsorial',
  massSongTitle('aclamacion'),
  'Aclamación antes del Evangelio',
  massSongTitle('ofertorio'),
  massSongTitle('cordero'),
  'Cordero de Dios',
  massSongTitle('comunion'),
  massSongTitle('final'),
])

function massViewForSettings(sections: PrayerSection[], settings: PrayerBuildSettings): PrayerSection[] {
  const renderable = sections.filter(sectionHasRenderableContent)

  if (settings.priestMode) {
    return renderable
  }

  return renderable.filter((section) => CHOIR_MASS_TITLES.has(section.title))
}

function massSections(record: PrayerRecord, settings: PrayerBuildSettings): PrayerSection[] {
  if (isGoodFridayCelebration(settings)) {
    return goodFridayPassionSections(record, settings)
  }

  if (isEasterVigilCelebration(settings)) {
    return easterVigilMassSections(record, settings)
  }

  const massSettings = massGospelBuildSettings(record, settings)
  const readings = massReadingSections(record, massSettings)
  const songSection = (section: MassSongSectionKey) => choirSongSection(section, record, massSettings)

  const sections: PrayerSection[] = [
    // El canto de entrada va antes que "Ritos iniciales" -- Lucas, 30/08/2026: se canta
    // mientras entra la procesión, antes de que arranque el rito en sí.
    songSection('entrada'),
    massPart('Ritos iniciales'),
    ...massIntroductorySections(massSettings, songSection, shouldIncludeGloriaInMass(massSettings)),
    massPart('Liturgia de la Palabra'),
  ]

  let hasAcclamationSong = false
  let hasInsertedSequence = false

  function pushSequenceIfNeeded(): void {
    if (hasInsertedSequence) {
      return
    }

    const sequence = massSequenceSection(massSettings)
    if (sequence) {
      sections.push(sequence)
    }

    hasInsertedSequence = true
  }

  readings.forEach((section) => {
    if (section.title === 'Salmo responsorial') {
      sections.push(songSection('salmo'))
    }

    if (section.title === 'Aclamación antes del Evangelio') {
      pushSequenceIfNeeded()
      sections.push(songSection('aclamacion'))
      hasAcclamationSong = true
    }

    if (section.title === 'Evangelio' && !hasAcclamationSong) {
      pushSequenceIfNeeded()
      sections.push(songSection('aclamacion'))
      sections.push(massGospelAcclamationSection(massSettings))
      hasAcclamationSong = true
    }

    sections.push(section)

    if (section.title === 'Evangelio') {
      sections.push(massPostGospelAcclamationSection())
    }
  })

  sections.push(
    ...massWordAfterReadingsSections(massSettings, shouldIncludeCreedInMass(massSettings), songSection),
    massPart('Liturgia eucarística'),
    ...massEucharisticSections(massSettings, songSection),
    massPart('Rito de la comunión'),
    ...massCommunionSections(massSettings, songSection),
  )

  if (isHolyThursdayCelebration(massSettings)) {
    sections.push(...holyThursdayTransferSections(massSettings, songSection))
  } else {
    sections.push(massPart('Ritos conclusivos'), ...massConcludingSections(massSettings, songSection))
  }

  return massViewForSettings(sections, settings)
}

export function buildSections(hour: HourKey, record: PrayerRecord, settings: PrayerBuildSettings): PrayerSection[] {
  switch (hour) {
    case 'invitatorium': {
      const sections: PrayerSection[] = [
        ...invitatorySections(record, settings).filter((section) => hasText(section.content) || section.alternatives?.length),
        {
          title: 'Conclusión',
          content: conclusion('short'),
          quiet: true,
        },
      ]

      return annotateSectionsForHour(hour, sections)
    }
    case 'officium':
      return annotateSectionsForHour(hour, officiumSections(record, settings))
    case 'laudes':
      return annotateSectionsForHour(hour, commonHourSections(record, settings, hour))
    case 'tertia':
    case 'sexta':
    case 'nona':
      return annotateSectionsForHour(hour, commonHourSections(record, settings, hour))
    case 'vesperae':
      return annotateSectionsForHour(hour, commonHourSections(record, settings, hour))
    case 'completorium':
      return annotateSectionsForHour(hour, completoriumSections(record, settings))
    case 'evangelium':
      return annotateSectionsForHour(hour, massSections(record, settings))
  }
}

function capitalize(value: string): string {
  return value ? value.charAt(0).toUpperCase() + value.slice(1) : ''
}

function localizedNameToken(token: string): string {
  if (token === 'and') return 'y'
  if (token === 'of') return 'de'
  if (token === 'the') return ''
  if (token === 'great') return 'Magno'
  if (token === 'nazianzen') return 'Nacianceno'
  if (token === 'rome') return 'Roma'
  if (token === 'sicily') return 'Sicilia'
  if (token === 'padua') return 'Padua'
  if (token === 'egypt') return 'Egipto'

  return optionNameTranslations[token] ?? capitalize(token)
}

function localizedRoleToken(token: string): string {
  if (token === 'and') return 'y'
  if (token === 'of') return 'de'

  return optionRoleTranslations[token] ?? optionNameTranslations[token] ?? token
}

function localizedSaintTitle(id: string): string {
  const tokens = id.split('_').filter(Boolean)
  const roleIndex = tokens.findIndex((token) => Boolean(optionRoleTranslations[token]))

  if (roleIndex < 0) {
    return ''
  }

  const femaleNames = new Set(['agatha', 'agnes', 'catherine', 'clare', 'lucy', 'mary', 'monica', 'teresa'])
  const prefix = femaleNames.has(tokens[0] ?? '') ? 'Santa' : 'San'
  const name = tokens
    .slice(0, roleIndex)
    .map(localizedNameToken)
    .filter(hasText)
    .join(' ')
  const roles = tokens
    .slice(roleIndex)
    .map(localizedRoleToken)
    .filter(hasText)
    .join(' ')

  return [name ? `${prefix} ${name}` : '', roles].filter(hasText).join(', ')
}

const seasonOptionNames: Record<string, string> = {
  ordinary_time: 'del Tiempo Ordinario',
  advent: 'de Adviento',
  christmas: 'de Navidad',
  lent: 'de Cuaresma',
  easter: 'de Pascua',
}

function seasonalWeekdayTitle(id: string): string | undefined {
  const match = id.match(/^(ordinary_time|advent|christmas|lent|easter)_(\d+)_(monday|tuesday|wednesday|thursday|friday|saturday|sunday)$/)
  if (!match) {
    return undefined
  }

  const season = seasonOptionNames[match[1]]
  const week = Number(match[2])
  const weekday = match[3]

  if (weekday === 'sunday') {
    return `${week}º domingo ${season}`
  }

  return `${weekdayOptionNames[weekday]} de la ${week}ª semana ${season}`
}

function localizedOptionTitleFromId(id: string): string {
  const fixed = fixedOptionTitles[id]
  if (fixed) {
    return fixed
  }

  const seasonal = seasonalWeekdayTitle(id)
  if (seasonal) {
    return seasonal
  }

  const saintTitle = localizedSaintTitle(id)
  if (saintTitle) {
    return saintTitle
  }

  return id
    .split('_')
    .map((token) => localizedNameToken(token))
    .filter(hasText)
    .join(' ')
}

export function optionTitle(record: PrayerRecord, index: number): string {
  const label = asText(record, OPTION_LABEL_KEY)
  if (hasText(label)) {
    return label
  }

  const id = typeof record.id === 'string' ? record.id : ''
  if (id) {
    return localizedOptionTitleFromId(id)
  }

  return `Opción ${index + 1}`
}
