function normalizeText(value: string): string {
  return value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
}

function collectText(value: unknown, seen = new Set<unknown>()): string {
  if (typeof value === 'string') {
    return value
  }

  if (!value || typeof value !== 'object' || seen.has(value)) {
    return ''
  }

  seen.add(value)

  if (Array.isArray(value)) {
    return value.map((item) => collectText(item, seen)).join(' ')
  }

  return Object.entries(value as Record<string, unknown>)
    .filter(([key]) => !key.startsWith('__'))
    .map(([, item]) => collectText(item, seen))
    .join(' ')
}

function asText(record: PrayerRecord, key: string): string {
  const value = record[key]

  return typeof value === 'string' ? value.trim() : ''
}

function massReadings(record: PrayerRecord): PrayerRecord[] {
  return Array.isArray(record.lecturas)
    ? record.lecturas.filter((reading): reading is PrayerRecord => Boolean(reading && typeof reading === 'object'))
    : []
}

function massReadingType(record: PrayerRecord): string {
  return asText(record, 'type').toUpperCase()
}

function isMassPsalmType(type: string): boolean {
  return type === 'PSALM' || type === 'CELEBRATION_PSALM' || type.endsWith('PSALM')
}

function isMassAcclamationType(type: string): boolean {
  return type === 'ACCLAMATION' || type === 'CELEBRATION_ACCLAMATION'
}

function massPsalmRefrain(ref: string): string {
  const value = ref.split(':').pop()?.trim() ?? ''

  return value.replace(/^_+|_+$/g, '').trim()
}

function massPsalmContent(ref: string, text: string): string {
  const refrain = massPsalmRefrain(ref)

  if (!hasText(refrain)) {
    return text
  }

  const responseLine = `$R.$ ${refrain}`
  const expandedText = text.replace(/\s*R\.(?=\s|$)/g, `\n${responseLine}`)

  return [responseLine, expandedText].filter(hasText).join('\n\n')
}

function dayPsalmText(record: PrayerRecord): string {
  const psalm = massReadings(record).find((reading) => {
    const type = massReadingType(reading)

    return isMassPsalmType(type) && hasText(asText(reading, 'texto'))
  })

  return psalm ? massPsalmContent(asText(psalm, 'ref'), asText(psalm, 'texto')) : ''
}

function calendarText(settings: PrayerBuildSettings): string {
  return normalizeText(
    [
      settings.celebration,
      settings.rank,
      settings.cycle,
      ...(settings.seasons ?? []),
    ]
      .filter(Boolean)
      .join(' '),
  )
}

function isLent(settings: PrayerBuildSettings): boolean {
  const text = calendarText(settings)

  return text.includes('lent') || text.includes('cuaresma')
}

function commonAcclamationVerse(settings: PrayerBuildSettings): string {
  const text = calendarText(settings)

  if (text.includes('advent') || text.includes('adviento')) {
    return 'Muéstranos, Señor, tu misericordia y danos tu salvación.'
  }

  if (text.includes('christmas') || text.includes('navidad') || text.includes('epifania')) {
    return 'Nos ha amanecido un día sagrado; venid, naciones, adorad al Señor, porque hoy una gran luz ha bajado a la tierra.'
  }

  if (isLent(settings)) {
    return 'No solo de pan vive el hombre, sino de toda palabra que sale de la boca de Dios.'
  }

  if (text.includes('pentecost')) {
    return 'Ven, Espíritu Santo, llena los corazones de tus fieles y enciende en ellos el fuego de tu amor.'
  }

  if (text.includes('easter') || text.includes('pascua') || text.includes('ascension')) {
    return 'Ha resucitado Cristo, que creó todas las cosas y se compadeció del género humano.'
  }

  if (text.includes('martir') || text.includes('martyr')) {
    return 'Dichosos los perseguidos por causa de la justicia, porque de ellos es el reino de los cielos.'
  }

  if (text.includes('virgen') || text.includes('maria')) {
    return 'Dichosa tú, Virgen María, que has creído, porque lo que te ha dicho el Señor se cumplirá.'
  }

  return 'Tus palabras, Señor, son espíritu y vida; tú tienes palabras de vida eterna.'
}

function cleanInlineMarkers(value: string): string {
  return value
    .replace(/_([^_]+)_/g, '$1')
    .replace(/\$([^$]+)\$/g, '$1')
    .replace(/\$/g, '')
    .trim()
}

function scriptureCaption(value?: string): string {
  const text = value?.trim() ?? ''
  const italic = text.match(/_([^_]+)_/)?.[1]?.trim()

  if (italic) {
    return italic
  }

  const afterCitation = text.match(/:\s*(.+)$/s)?.[1]?.trim()

  return afterCitation ? cleanInlineMarkers(afterCitation) : ''
}

function dayGospelCaption(record: PrayerRecord, settings: PrayerBuildSettings): string {
  const gospel = massReadings(record).find((reading) => {
    const type = massReadingType(reading)

    return type === 'GOSPEL' || type === 'CELEBRATION_GOSPEL'
  })

  return scriptureCaption(settings.massGospelReference) || scriptureCaption(gospel ? asText(gospel, 'ref') : '')
}

function dayAcclamationText(record: PrayerRecord, settings: PrayerBuildSettings): string {
  const acclamation = massReadings(record).find((reading) => {
    const type = massReadingType(reading)

    return isMassAcclamationType(type) && (hasText(asText(reading, 'ref')) || hasText(asText(reading, 'texto')))
  })

  const response = isLent(settings) ? '$Todos.$ Honor y gloria a ti, Señor Jesús.' : '$Todos.$ Aleluya.'
  const verse = acclamation
    ? asText(acclamation, 'texto') || scriptureCaption(asText(acclamation, 'ref')) || dayGospelCaption(record, settings)
    : dayGospelCaption(record, settings) || commonAcclamationVerse(settings)

  return [response, `$Cantor.$ ${verse}`, response].filter(hasText).join('\n\n')
}

function contextTags(record: PrayerRecord, settings: PrayerBuildSettings): Set<MassSongTag> {
  const liturgicalText = calendarText(settings)
  const fullText = normalizeText([liturgicalText, collectText(record)].filter(Boolean).join(' '))
  const tags = new Set<MassSongTag>()

  if (liturgicalText.includes('ordinary') || liturgicalText.includes('ordinario')) tags.add('ordinary')
  if (liturgicalText.includes('advent') || liturgicalText.includes('adviento')) tags.add('advent')
  if (liturgicalText.includes('christmas') || liturgicalText.includes('navidad')) tags.add('christmas')
  if (liturgicalText.includes('lent') || liturgicalText.includes('cuaresma')) tags.add('lent')
  if (liturgicalText.includes('easter') || liturgicalText.includes('pascua')) tags.add('easter')
  if (liturgicalText.includes('corpus') || liturgicalText.includes('cuerpo y sangre')) tags.add('corpus')
  if (liturgicalText.includes('trinidad') || liturgicalText.includes('trinity')) tags.add('trinity')
  if (liturgicalText.includes('pentecost')) tags.add('pentecost')
  if (liturgicalText.includes('pentecost') || liturgicalText.includes('espiritu santo') || liturgicalText.includes('paraclito')) tags.add('spirit')
  if (liturgicalText.includes('maria') || liturgicalText.includes('virgen') || liturgicalText.includes('madre')) tags.add('mary')
  if (liturgicalText.includes('martir')) tags.add('martyr')
  if (liturgicalText.includes('santo') || liturgicalText.includes('santos') || liturgicalText.includes('san ')) tags.add('saints')
  if (fullText.includes('eucarist') || fullText.includes('pan de vida') || /\b(?:pan|vino)\b/.test(fullText)) tags.add('eucharist')
  if (fullText.includes('mision') || fullText.includes('envia') || fullText.includes('apostol')) tags.add('mission')
  if (fullText.includes('palabra') || fullText.includes('evangelio')) tags.add('word')
  if (fullText.includes('perdon') || fullText.includes('misericord')) tags.add('forgiveness')
  if (fullText.includes('paz')) tags.add('peace')
  if (fullText.includes('alegr')) tags.add('joy')
  if (fullText.includes('ofrenda') || fullText.includes('altar')) tags.add('offering')
  if (fullText.includes('comunion')) tags.add('communion')

  return tags
}

function scoreSong(song: SongSuggestion, section: MassSongSectionKey, tags: Set<MassSongTag>): number {
  const seasonalTags: MassSongTag[] = ['advent', 'christmas', 'lent', 'easter', 'pentecost']
  const matchingTags = song.tags.filter((tag) => tags.has(tag))
  let score = (song.sections[0] === section ? 18 : 0) + (matchingTags.length ? song.priority ?? 0 : Math.min(song.priority ?? 0, 2))

  for (const tag of song.tags) {
    if (tags.has(tag)) {
      score += tag === 'ordinary' ? 5 : 24
    }
  }

  for (const tag of seasonalTags) {
    if (song.tags.includes(tag) && !tags.has(tag)) {
      score -= 42
    }
  }

  if (song.tags.includes('corpus') && !tags.has('corpus') && !tags.has('eucharist')) {
    score -= 36
  }

  if (section === 'comunion' && (tags.has('corpus') || tags.has('eucharist'))) {
    score += song.tags.includes('eucharist') ? 16 : 0
  }

  if (section === 'salmo' && song.tags.includes('psalm')) {
    score += 8
  }

  return score
}

function matchedTagText(song: SongSuggestion, tags: Set<MassSongTag>): string {
  const matches = song.tags.filter((tag) => tags.has(tag)).map((tag) => tagLabels[tag])

  return matches.length ? matches.join(', ') : 'encaje general de la sección'
}

function sourceLink(source: SongSource): string {
  return `<a href="${escapeHtml(source.url)}" target="_blank" rel="noreferrer">${escapeHtml(source.label)}</a>`
}

function liturgicalTextBlock(title: string, text: string): string {
  return [
    '<div class="song-liturgical-text">',
    `<p><span class="rubric">Texto litúrgico.</span> ${escapeHtml(title)}</p>`,
    ...text
      .split(/\n{2,}/)
      .map((paragraph) => `<p>${escapeHtml(paragraph).replace(/\n/g, '<br>')}</p>`),
    '</div>',
  ].join('')
}

function liturgicalSongText(song: SongSuggestion, settings: PrayerBuildSettings, record: PrayerRecord): string {
  const title = normalizeText(song.title)

  if (song.sections.includes('penitencial') && title.includes('kyrie')) {
    return liturgicalTextBlock(
      'Kyrie eleison',
      '$Sacerdote/diácono.$ Kyrie, eleison.\n$Pueblo.$ Kyrie, eleison.\n\n$Sacerdote/diácono.$ Christe, eleison.\n$Pueblo.$ Christe, eleison.\n\n$Sacerdote/diácono.$ Kyrie, eleison.\n$Pueblo.$ Kyrie, eleison.',
    )
  }

  if (song.sections.includes('penitencial') && title.includes('senor ten piedad')) {
    return liturgicalTextBlock(
      'Señor, ten piedad',
      '$Sacerdote/diácono.$ Señor, ten piedad.\n$Pueblo.$ Señor, ten piedad.\n\n$Sacerdote/diácono.$ Cristo, ten piedad.\n$Pueblo.$ Cristo, ten piedad.\n\n$Sacerdote/diácono.$ Señor, ten piedad.\n$Pueblo.$ Señor, ten piedad.',
    )
  }

  if (song.sections.includes('gloria') && title.includes('gloria')) {
    return liturgicalTextBlock(
      'Gloria',
      '$Todos.$ Gloria a Dios en el cielo,\ny en la tierra paz a los hombres que ama el Señor.\nPor tu inmensa gloria te alabamos,\nte bendecimos, te adoramos,\nte glorificamos, te damos gracias,\nSeñor Dios, Rey celestial,\nDios Padre todopoderoso.\n\nSeñor, Hijo único, Jesucristo.\nSeñor Dios, Cordero de Dios, Hijo del Padre;\ntú que quitas el pecado del mundo,\nten piedad de nosotros;\ntú que quitas el pecado del mundo,\natiende nuestra súplica;\ntú que estás sentado a la derecha del Padre,\nten piedad de nosotros;\nporque sólo tú eres Santo,\nsólo tú Señor,\nsólo tú Altísimo, Jesucristo,\ncon el Espíritu Santo\nen la gloria de Dios Padre. Amén.',
    )
  }

  if (song.sections.includes('credo')) {
    if (title.includes('apostolico')) {
      return liturgicalTextBlock('Credo apostólico', CREDO_APOSTOLICO_ES)
    }

    if (title.includes('iii')) {
      return liturgicalTextBlock('Credo III', CREDO_III_LATIN)
    }

    return liturgicalTextBlock('Credo niceno', CREDO_NICENO_ES)
  }

  if (song.sections.includes('salmo')) {
    const psalm = dayPsalmText(record)

    if (psalm) {
      return liturgicalTextBlock('Salmo responsorial del día', psalm)
    }
  }

  if (song.sections.includes('aclamacion')) {
    const acclamation = dayAcclamationText(record, settings)

    if (acclamation) {
      return liturgicalTextBlock('Aclamación antes del Evangelio del día', acclamation)
    }
  }

  if (song.sections.includes('santo')) {
    return liturgicalTextBlock(
      'Santo',
      '$Todos.$ Santo, Santo, Santo es el Señor,\nDios del universo.\nLlenos están el cielo y la tierra de tu gloria.\nHosanna en el cielo.\nBendito el que viene en nombre del Señor.\nHosanna en el cielo.',
    )
  }

  if (song.sections.includes('memorial')) {
    if (title.includes('cada vez')) {
      return liturgicalTextBlock(
        'Aclamación memorial',
        '$Sacerdote.$ Aclamemos el Misterio de la fe.\n\n$Pueblo.$ Cada vez que comemos de este pan y bebemos de este cáliz, anunciamos tu muerte, Señor, hasta que vuelvas.',
      )
    }

    if (title.includes('por tu cruz')) {
      return liturgicalTextBlock(
        'Aclamación memorial',
        '$Sacerdote.$ Este es el Misterio de la fe.\n\n$Pueblo.$ Por tu cruz y resurrección nos has salvado, Señor.',
      )
    }

    return liturgicalTextBlock(
      'Aclamación memorial',
      '$Sacerdote.$ Este es el Misterio de la fe.\n\n$Pueblo.$ Anunciamos tu muerte, proclamamos tu resurrección. ¡Ven, Señor Jesús!',
    )
  }

  if (song.sections.includes('amen')) {
    return liturgicalTextBlock('Gran Amén', '$Pueblo.$ Amén.')
  }

  if (song.sections.includes('padrenuestro')) {
    return liturgicalTextBlock('Padrenuestro', `$Todos.$ ${lordPrayer(settings.lordPrayerLanguage)}`)
  }

  if (song.sections.includes('cordero')) {
    return liturgicalTextBlock(
      'Cordero de Dios',
      '$Todos.$ Cordero de Dios, que quitas el pecado del mundo, ten piedad de nosotros.\n\n$Todos.$ Cordero de Dios, que quitas el pecado del mundo, ten piedad de nosotros.\n\n$Todos.$ Cordero de Dios, que quitas el pecado del mundo, danos la paz.',
    )
  }

  return ''
}

function suggestionContent(song: SongSuggestion, tags: Set<MassSongTag>, settings: PrayerBuildSettings, record: PrayerRecord): string {
  const source = songSources[song.source]
  const liturgicalText = liturgicalSongText(song, settings, record)
  const includedLyrics = song.lyrics ? liturgicalTextBlock(song.lyricsTitle ?? song.title, song.lyrics) : ''
  const hasIncludedText = Boolean(liturgicalText || includedLyrics)

  return [
    '<div class="song-suggestion">',
    `<p class="song-suggestion-title">${escapeHtml(song.title)}</p>`,
    `<p><span class="rubric">Encaje.</span> ${escapeHtml(song.note)}</p>`,
    `<p><span class="rubric">Prioridad por día.</span> ${escapeHtml(matchedTagText(song, tags))}</p>`,
    liturgicalText,
    includedLyrics,
    `<p><span class="rubric">Fuente.</span> ${sourceLink(source)} <span class="song-source-note">${escapeHtml(source.note)}</span></p>`,
    '<div class="song-source-action">',
    `<span class="song-source-action-title">${hasIncludedText ? 'Texto incluido' : 'Letra y acordes'}</span>`,
    `<span>${hasIncludedText ? 'Consulta la fuente enlazada para melodía, partitura o acordes.' : 'Consultar en la fuente enlazada.'}</span>`,
    '</div>',
    '</div>',
  ].join('')
}

export function massSongTitle(section: MassSongSectionKey): string {
  return sectionLabels[section]
}

export function massSongAlternatives(
  section: MassSongSectionKey,
  record: PrayerRecord,
  settings: PrayerBuildSettings,
): PrayerSectionAlternative[] {
  const tags = contextTags(record, settings)

  return massSongSuggestions
    .filter((song) => song.sections.includes(section))
    .map((song) => ({
      song,
      score: scoreSong(song, section, tags),
    }))
    .sort((left, right) => right.score - left.score || left.song.title.localeCompare(right.song.title, 'es'))
    .map(({ song }) => ({
      label: song.title,
      content: suggestionContent(song, tags, settings, record),
    }))
}
